INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2556', 'spa', 'Malo, malvado, perverso; de corrupción moral, efectos dañinos, o personas que practican la maldad.', 'Un término moral amplio que abarca todo el espectro de lo malo o perverso. En los Evangelios aparece con mayor frecuencia como sustantivo: ''lo malo'' o ''cosas malas'', nombrando la corrupción moral contra la que Jesús advirtió (Mr 7:21) y la maldad que la multitud no podía articular cuando Pilato preguntó ''¿Qué mal ha hecho?'' (Mt 27:23). Los pocos usos no morales (Lc 16:25, ''cosas malas'') y los usos personales (''los malos'', Mt 21:41) muestran su flexibilidad entre referentes abstractos, concretos y personales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2557', 'spa', 'Criminal, malhechor; quien comete actos malvados, especialmente en un contexto legal o judicial', 'Se refiere a un criminal o malhechor en el sentido formal y judicial: alguien identificado por la ley como autor de malas acciones. Las cuatro apariciones en el Nuevo Testamento llevan una fuerte carga judicial o de castigo. En Lc 23:32-33, 39, los dos hombres crucificados junto a Jesús son identificados como malhechores, y toda la tradición de traducción refleja ese peso legal. Pablo aplica el término a sí mismo en 2 Ti 2:9, con amarga ironía: sufre encarcelamiento ''como un criminal'' por proclamar el evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2559', 'spa', 'Maltratar, hacer daño u oprimir a alguien; infligir sufrimiento o injusticia.', 'Kakoo significa tratar mal a alguien, causándole daño o angustia. En el NT aparece exclusivamente en Hechos, trazando un hilo de persecución a lo largo de la historia de la salvación: Dios anuncia a Abraham que sus descendientes serán esclavizados y maltratados durante cuatrocientos años (Hch 7:6), el Faraón actúa con astucia contra Israel (Hch 7:19), Herodes ataca violentamente a los líderes de la iglesia (Hch 12:1) y multitudes hostiles en Iconio envenenan los ánimos contra los creyentes (Hch 14:2). La promesa del Señor a Pablo en Corinto —«nadie te hará daño» (Hch 18:10)— constituye el contrapunto de gracia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2560', 'spa', 'Mal, gravemente (referido a enfermedad); incorrectamente, perversamente (referido a conducta moral o habla). El adverbio κακῶς abarca dos registros di', 'Mal, gravemente (referido a enfermedad); incorrectamente, perversamente (referido a conducta moral o habla). El adverbio κακῶς abarca dos registros distintos en el Nuevo Testamento. En su uso médico dominante, modifica condiciones de enfermedad y aflicción (''los que estaban gravemente enfermos''), apareciendo doce veces en los resúmenes formulaicos de sanación de los Evangelios (Mt 4:24, 8:16, 9:12). En su uso ético menos frecuente, describe habla o conducta moralmente incorrecta, como cuando Jesús desafía a sus acusadores en su juicio: ''si hablé mal, da testimonio del mal'' (Jn 18:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2561', 'spa', 'maltrato, opresion; trato cruel o abusivo contra alguien', 'Este sustantivo describe un trato duro o cruel, especialmente hacia quienes deberian ser protegidos o cuidados. En Hechos 7:34, Esteban cita las palabras de Dios a Moises: ''Ciertamente he visto el maltrato (κάκωσιν) de mi pueblo en Egipto''. El termino designa la opresion que Israel sufrio bajo el Faraon: trabajos forzados, brutalidad, infanticidio. Dios ve la κάκωσις y responde con liberacion. La palabra aparece en contextos de injusticia sistematica o abuso de poder, y la respuesta constante de Dios es actuar en favor de los oprimidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2562', 'spa', 'cana, paja, rastrojo; tallos secos del grano tras la cosecha', 'Este sustantivo se refiere al tallo o paja del grano, especialmente lo que queda despues de la cosecha: el rastrojo. En 1 Corintios 3:12, aparece en la metafora paulina de edificar sobre el fundamento de Cristo: algunos construyen con ''oro, plata, piedras preciosas'', otros con ''madera, heno, paja (καλάμην)''. El rastrojo representa material sin valor y combustible que no puede resistir el fuego. Pablo advierte que la obra de cada constructor sera probada, y lo edificado con materiales perecederos como la paja sera consumido. Solo lo que sobreviva al fuego recibira recompensa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2563', 'spa', 'Caña como planta o vara fabricada de ella; también pluma para escribir hecha de una caña afilada. Κάλαμος es uno de esos objetos humildes y cotidianos', 'Caña como planta o vara fabricada de ella; también pluma para escribir hecha de una caña afilada. Κάλαμος es uno de esos objetos humildes y cotidianos que la Escritura pone al servicio de imágenes vívidas. Como planta, evoca los pantanos azotados por el viento junto al Jordán: Jesús pregunta a las multitudes «¿Qué salisteis a ver? ¿Una caña sacudida por el viento?» (Mt 11:7). Como vara, se convirtió en un accesorio cruel en la burla de Cristo: los soldados pusieron una caña en su mano como cetro y luego lo golpearon con ella (Mt 27:29-30). En una única aparición (3 Jn 1:13), la palabra toma su significado especializado de pluma para escribir — una caña afilada mojada en tinta — recordándonos que la tecnología del mundo antiguo para registrar la Escritura era en sí misma un don de la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2564', 'spa', 'Llamar, nombrar, convocar o invitar: designar con un nombre, llamar a la salvación, convocar a alguien, o invitar a un banquete.', 'El verbo καλέω es uno de los más versátiles del Nuevo Testamento, tendiendo un puente entre el habla cotidiana y la teología más profunda. En su sentido más sencillo significa dar un nombre: «llamarás su nombre Jesús» (Mt 1:21). Pero Pablo lo transformó en término técnico del llamamiento soberano de Dios a la salvación: «a los que llamó, también justificó» (Ro 8:30). En los relatos evangélicos conserva el sentido básico de convocar —Herodes convocando en secreto a los magos (Mt 2:7), Jesús llamando a sus discípulos (Mt 4:21). El sentido más concreto, «invitar», emerge con claridad en las parábolas de los banquetes (Mt 22:3-9; Lc 14:7-24). Cuatro acepciones distintas en un solo verbo: el contexto lo es todo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2565', 'spa', 'olivo cultivado; el olivo domesticado en contraste con el olivo silvestre (acebuche)', 'Este sustantivo designa el olivo cultivado o de huerto, en contraste con el olivo silvestre (ἀγριέλαιος). En Romanos 11:24, Pablo describe a los gentiles como ramas de un olivo silvestre injertadas ''contra naturaleza'' en un olivo cultivado (καλλιέλαιος). La metáfora es botánicamente inversa: normalmente se injerta una variedad cultivada sobre un patrón silvestre, no al revés. El punto de Pablo es precisamente lo antinatural de la inclusión gentil: Dios ha hecho algo inesperado y lleno de gracia, injertando ramas silvestres en el árbol cultivado de Israel para compartir la ''rica raíz'' de los patriarcas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2566', 'spa', 'muy bien, mejor; de manera excelente o más apropiada', 'Es la forma comparativa de καλός (bueno, hermoso), que significa ''mejor'' o ''de manera más apropiada''. En Hechos 25:10, Pablo responde a la sugerencia de Festo de ser juzgado en Jerusalén: ''Ante el tribunal del César estoy, donde debo (κάλλιον) ser juzgado.'' El comparativo afirma el derecho de Pablo a la jurisdicción romana: era ''más apropiado'' que un ciudadano romano, no acusado de ningún delito contra la ley judía, fuese juzgado ante el tribunal del César y no ante un Sanedrín hostil. Pablo insiste en la corrección legal de su apelación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2567', 'spa', 'maestras de lo bueno; quienes enseñan la virtud y la vida piadosa', 'Este adjetivo compuesto describe a quienes enseñan lo bueno y virtuoso. En Tito 2:3, Pablo instruye que las mujeres mayores deben ser ''maestras de lo bueno'' (καλοδιδασκάλους), formando a las más jóvenes en piedad y virtud. El término combina ''bueno'' o ''hermoso'' con ''maestro'', destacando tanto el contenido (la bondad moral) como el papel (la instrucción). Pablo concibe a las mujeres cristianas mayores como mentoras de las más jóvenes, no solo en destrezas domésticas sino en la formación del carácter, modelando y enseñando una vida virtuosa dentro de la comunidad de fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2568', 'spa', 'Buenos Puertos (Καλοὶ Λιμένες); puerto en la costa sur de Creta', 'Un puerto en la costa sur de Creta donde el barco de Pablo se detuvo durante su viaje a Roma. Hechos 27:8 lo menciona como el lugar donde la tripulación debatió si invernar allí o continuar la navegación, una decisión que condujo al naufragio cuando ignoraron la advertencia de Pablo. El nombre significa «Buenos Puertos» o «Puertos Hermosos», probablemente un título descriptivo directo. Las fuentes antiguas y modernas lo identifican con una bahía cercana a la ciudad cretense de Lasea. Este detalle narrativo ancla el relato de Lucas en la geografía real del Mediterráneo y sus condiciones de navegación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2569', 'spa', 'hacer el bien, obrar virtuosamente; perseverar en hacer lo correcto', 'Este verbo significa hacer lo bueno o correcto, obrar con virtud. En 2 Tesalonicenses 3:13, Pablo exhorta: ''No os canséis de hacer el bien (καλοποιοῦντες).'' El participio describe una acción moral continua, no un acto aislado de bondad, sino un estilo de vida virtuoso. La preocupación de Pablo es que los tesalonicenses pudieran desanimarse o agotarse en su compromiso con la rectitud, quizás frustrados por la ociosidad ajena o la oposición. Los insta a perseverar en el bien obrar a pesar del cansancio o la falta de recompensa visible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2570', 'spa', 'Bueno, bello, excelente; moralmente encomiable o estéticamente hermoso, también como elemento del topónimo «Buenos Puertos».', 'Mientras que ἀγαθός (G0018) subraya la bondad moral intrínseca, καλός posee una dimensión estética más rica: lo bello, noble o admirable a la vista y a la experiencia. El vocablo hereda del griego clásico la fusión de belleza física y excelencia moral (καλοκαγαθία). Jesús habla de «buena tierra» y «buen fruto» (Mt 13:8, 23), donde καλός sugiere no solo aptitud moral sino un florecimiento casi visible. La acepción puramente estética aflora en Lc 21:5 («piedras hermosas») y Mt 13:45 («perlas hermosas»). En Hch 27:8 se conserva como elemento de topónimo: Καλοὶ Λιμένες, «Buenos Puertos». El alemán gut y schön juntos abarcan lo que καλός expresa en una sola palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2571', 'spa', 'Velo o cobertura; usado figuradamente de la cobertura espiritual sobre la mente al leer el antiguo pacto', 'Designa un velo o cobertura colocado sobre algo para ocultarlo. Las cuatro apariciones neotestamentarias se concentran en un solo pasaje, 2 Corintios 3:13-16, donde Pablo recurre a la imagen de Moisés cubriéndose el rostro con un velo. El κάλυμμα se convierte en una poderosa metáfora de la ceguera espiritual: un velo cubre el corazón de quienes leen el antiguo pacto sin reconocer a Cristo. Cuando alguien se vuelve al Señor, ese velo es quitado, revelando la gloria transformadora del Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2572', 'spa', 'Cubrir, ocultar o velar; colocar algo encima para tapar, proteger o esconder de la vista.', 'Kalupto significa cubrir u ocultar colocando algo sobre una persona u objeto. En los Evangelios describe las olas del mar cubriendo una barca (Mt 8:24), una lámpara tapada con una vasija (Lc 8:16) y el clamor aterrorizado pidiendo que los montes caigan y cubran a la gente (Lc 23:30). Pablo lo emplea para referirse al evangelio que está velado para los que se pierden (2 Co 4:3). El español ''cubrir'' y el francés ''couvrir'' proceden de la misma raíz latina, reforzando el significado central uniforme a lo largo de las ocho apariciones en el Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2573', 'spa', 'Bien, correctamente, apropiadamente — adverbio que afirma que algo se hace de manera buena, adecuada o encomiable', 'Bien, correctamente, apropiadamente — adverbio que afirma que algo se hace de manera buena, adecuada o encomiable');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2574', 'spa', 'Camello; el gran animal doméstico, usado en dichos proverbiales y en descripciones de vestimenta ascética.', 'Kamelos es el préstamo griego de la palabra semítica para camello (hebreo gamal), refiriéndose a la conocida bestia de carga del antiguo Cercano Oriente. En el NT aparece en dos contextos memorables: el dicho proverbial sobre un camello pasando por el ojo de una aguja, empleado por Jesús para ilustrar cuán difícil es para los ricos entrar en el reino de Dios (Mt 19:24; Mr 10:25; Lc 18:25), y la descripción de la vestimenta de Juan el Bautista hecha de pelo de camello (Mt 3:4; Mr 1:6). Jesús también lo usa al reprochar a los fariseos que «cuelan el mosquito y se tragan el camello» (Mt 23:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2575', 'spa', 'Horno o fragua; fuego intenso para fundir o quemar, frecuente en imágenes de juicio divino', 'Se refiere a un horno, fragua o caldera: una estructura de calor extremo empleada para fundir metal o cocer cerámica. En el Nuevo Testamento aparece exclusivamente en contextos de juicio e imaginería apocalíptica. Jesús advierte que los malhechores serán arrojados al horno de fuego (Mt 13:42, 50). En Apocalipsis, los pies del Señor brillan como bronce refinado en un horno (Ap 1:15) y sube humo como de un gran horno (Ap 9:2). La imagen transmite tanto la intensidad purificadora del fuego como la solemnidad del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2578', 'spa', 'Doblar, inclinar (especialmente la rodilla); acto de adoracion, sumision o reverencia solemne.', 'Describe el acto fisico de doblar o inclinar, casi siempre en el Nuevo Testamento con referencia a la rodilla. Cada aparicion conlleva un peso teologico profundo: doblar la rodilla ante Dios como gesto de adoracion o sumision. Pablo dobla sus rodillas ante el Padre en oracion (Ef 3:14), y el gran himno cristologico declara que toda rodilla se doblara al nombre de Jesus (Fil 2:10). En Rom 11:4, Dios ha preservado siete mil que no han doblado la rodilla ante Baal, y en Rom 14:11 la cita de Isaias proclama que toda rodilla se doblara. El verbo une el gesto fisico con la entrega espiritual mas profunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2579', 'spa', 'Aunque, aun si (conjunción concesiva); al menos (partícula escalar mínima). La forma de crasis κἄν (= καὶ ἐάν o καὶ ἄν) funciona principalmente como c', 'Aunque, aun si (conjunción concesiva); al menos (partícula escalar mínima). La forma de crasis κἄν (= καὶ ἐάν o καὶ ἄν) funciona principalmente como conjunción concesiva en el Nuevo Testamento, introduciendo condiciones hipotéticas o extremas: ''aunque tenga que morir contigo'' (Mt 26:35), ''aunque beban veneno mortal'' (Mc 16:18). Aparece quince veces en este papel intensificador, enfatizando que el resultado se mantiene sin importar la condición. Una única aparición notable en Hch 5:15 cambia a un sentido escalar o minimizador (''al menos la sombra de Pedro''), donde la partícula marca el mínimo absoluto de expectativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2580', 'spa', 'Cana, una aldea de Galilea; escenario del primer milagro de Jesus y patria de Natanael.', 'Pequena aldea de Galilea, recordada como el escenario de la primera senal publica de Jesus: la conversion del agua en vino durante una boda (Jn 2:1-11). El Evangelio de Juan regresa a Cana como marcador geografico: Jesus se encuentra alli cuando sana a distancia al hijo del funcionario real en Capernaum (Jn 4:46), y Natanael es identificado como oriundo de Cana (Jn 21:2). El nombre se conserva de manera uniforme en las diversas lenguas, reflejando su origen semitico indeclinable. Su presencia reiterada en el Cuarto Evangelio la convierte en un punto de referencia narrativo clave.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2582', 'spa', 'Candace, título dinástico de la reina madre de Etiopía (Meroë)', 'Candace no era un nombre personal sino un título real de la reina madre de Meroë, el antiguo reino al sur de Egipto (actual Sudán). En Hechos 8:27, el eunuco etíope sirve como ''funcionario de la corte de Candace, reina de los etíopes, encargado de todo su tesoro''. El título indica una gobernante femenina poderosa o reina madre que ejercía autoridad considerable. El largo viaje del eunuco a Jerusalén para adorar demuestra el alcance de la influencia judía y prepara el terreno para la extensión del evangelio a África mediante la explicación de Isaías 53 por parte de Felipe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2583', 'spa', 'Regla, norma, medida; un principio o estandar por el cual se evalua algo, o una esfera definida de actividad.', 'Originalmente una vara recta o regla de medir usada por constructores, este sustantivo paso a significar una ''regla'' o ''estandar'' de medicion. Pablo lo emplea en 2 Corintios 10:13-16 para definir su ''esfera'' o ''campo'' de ministerio asignado por Dios, insistiendo en que no se gloria mas alla de la medida que le fue otorgada. En Ga 6:16 designa la ''regla'' o principio rector conforme al cual deben caminar los creyentes. Fil 3:16 llama igualmente a vivir segun el mismo ''estandar''. El espanol ''regla'' refleja directamente el latin regula, del cual deriva tambien el ingles rule.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2584', 'spa', 'Capernaúm, ciudad a orillas del lago en Galilea que sirvió como base principal del ministerio público de Jesús. Kapharnaoum (del hebreo kəfar Nachum, ', 'Capernaúm, ciudad a orillas del lago en Galilea que sirvió como base principal del ministerio público de Jesús. Kapharnaoum (del hebreo kəfar Nachum, ''aldea de Nahum'') era un asentamiento pesquero en la ribera noroeste del mar de Galilea. Tras dejar Nazaret, Jesús la adoptó como su hogar (Mt 4:13) y realizó allí numerosas sanaciones y enseñanzas, incluyendo la curación del siervo del centurión (Mt 8:5) y el discurso del Pan de Vida (Jn 6:59). A pesar de estas obras poderosas, la ciudad recibió reprensión profética por su incredulidad (Mt 11:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2585', 'spa', 'traficar, mercadear; comerciar con algo para lucro, especialmente con connotación de adulterar o corromper', 'Este verbo significa traficar, mercadear o comerciar con algo, frecuentemente con la connotación negativa de lucrar con lo que no debería venderse. En 2 Corintios 2:17, Pablo se distingue de los muchos que «trafican (καπηλεύοντες) con la palabra de Dios», afirmando que él habla con sinceridad, de parte de Dios y en la presencia de Dios. El término implica corromper o adulterar el evangelio por ganancia económica, tratando la verdad sagrada como mercancía en vez de un mensaje que debe proclamarse con fidelidad. Pablo insiste en que su predicación no busca provecho personal sino que nace de motivos puros ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2586', 'spa', 'Humo; el vapor visible que se eleva del fuego, usado en contextos de gloria teofánica, juicio y destrucción apocalíptica. Es la palabra griega común p', 'Humo; el vapor visible que se eleva del fuego, usado en contextos de gloria teofánica, juicio y destrucción apocalíptica. Es la palabra griega común para el humo: el vapor oscuro y ondulante producido por la combustión. Aunque el término es sencillo en su sentido literal, el NT lo emplea casi exclusivamente en contextos teológicos y apocalípticos cargados de significado. En Pentecostés, Pedro cita la profecía de Joel sobre «sangre y fuego y vapor de humo» (Hch 2:19). En Apocalipsis, el humo sube del incienso del altar de oro ante Dios (Ap 8:4), brota del abismo como humo de un gran horno (Ap 9:2) y asciende del tormento de Babilonia para siempre (Ap 14:11; 18:9, 18; 19:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2588', 'spa', 'Corazón; el ser interior como sede del pensamiento, la emoción, la voluntad y la vida espiritual.', 'En el Nuevo Testamento, καρδία es mucho más rico que su equivalente anatómico. Siguiendo al hebreo לֵב, designa la totalidad de la persona interior: sede del pensamiento («¿por qué pensáis mal en vuestros corazones?», Mt 9:4), de la emoción («no se turbe vuestro corazón», Jn 14:1), de la voluntad («propósito de corazón», Hch 11:23) y del discernimiento moral («los limpios de corazón verán a Dios», Mt 5:8). Todas las lenguas relevantes emplean su palabra nuclear para «corazón» —corazón, coeur, Herz, دل/قلب—, confirmando la metáfora universal del corazón como centro de la persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2590', 'spa', 'Fruto, producto o cosecha; usado literalmente de cultivos y figuradamente de resultados morales y espirituales.', 'El sustantivo καρπός (''fruto'') opera en dos registros en el Nuevo Testamento. Literalmente designa el producto agrícola: higos, uvas, grano, el rendimiento de la tierra y del árbol (Mt 21:19; Mr 4:7-8; Lc 13:6-9; Stg 5:7, 18; Ap 22:2 con sus doce clases de fruto). Figuradamente, es una de las metáforas éticas más importantes del NT: Juan el Bautista exige ''frutos dignos de arrepentimiento'' (Mt 3:8), Jesús advierte que por sus frutos los conoceréis (Mt 7:16-20), y Pablo despliega el ''fruto del Espíritu'' como amor, gozo, paz y más (Gá 5:22). El español ''fruto'' sirve para ambos sentidos, reflejando la naturalidad con que esta metáfora se transfiere entre lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2591', 'spa', 'Carpo, un cristiano en Troas con quien Pablo dejó su capa', 'Carpo aparece únicamente en 2 Timoteo 4:13, donde Pablo pide a Timoteo que traiga «la capa que dejé en Troas en casa de Carpo». Esta petición, junto con la mención de libros y pergaminos, traza un retrato conmovedor: Pablo encarcelado, enfrentando el invierno, necesitando su capa para el frío y sus libros para el estudio. Carpo era probablemente un creyente cristiano de Troas que hospedó a Pablo o resguardó sus pertenencias. Este pequeño detalle revela la humanidad de Pablo: incluso los apóstoles sienten frío, extrañan sus posesiones y dependen de la hospitalidad de los amigos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2592', 'spa', 'Dar fruto, producir cosecha; ya sea producto agrícola literal o productividad espiritual figurada.', 'Karpophoreo describe el acto de producir fruto, recurriendo a la profunda imaginería agrícola del mundo antiguo. Jesús lo emplea en la parábola del sembrador para distinguir la buena tierra que ''da fruto'' en abundancia (Mt 13:23; Mc 4:20; Lc 8:15). Pablo extiende la metáfora al ámbito espiritual, afirmando que los creyentes dan fruto para Dios (Ro 7:4; Col 1:6, 10). Las expresiones española ''dar fruto'' y francesa ''porter du fruit'' reflejan casi exactamente la estructura compuesta griega (karpos + phoreo), conservando la vívida imagen de llevar o producir cosecha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2593', 'spa', 'fructífero, que da fruto; productivo o fértil', 'Este adjetivo describe algo que da fruto o produce cosechas, ya sea en sentido literal de plantas o en sentido figurado de productividad. En Hechos 14:17, Pablo dice a los licaonios que Dios «no se dejó a sí mismo sin testimonio, haciendo el bien, dándoles lluvias del cielo y estaciones fructíferas (καρποφόρους)». El término describe la fertilidad agrícola: temporadas que producen cosecha, no sequía ni hambruna. La providencia de Dios en la naturaleza sirve como testimonio de su existencia y bondad incluso entre paganos que carecen de revelación especial. La fecundidad de la creación da testimonio del poder benévolo del Creador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2594', 'spa', 'perseverar con firmeza, resistir con paciencia; mantenerse constante pese a la adversidad', 'Este verbo significa perseverar con paciencia, resistir o mantenerse firme a pesar de las dificultades. En Hebreos 11:27 describe a Moisés: «Perseveró (ἐκαρτέρησεν) como viendo al Invisible». La palabra transmite una resistencia firme arraigada en la atención concentrada: Moisés soportó la hostilidad de Egipto y las penurias del desierto fijando su mirada en el Dios invisible. Καρτερέω no implica resignación pasiva, sino perseverancia activa y resuelta, manteniéndose fiel cuando las circunstancias justificarían abandonar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2595', 'spa', 'Mota, brizna, astilla; pequeño fragmento seco de madera o paja; usado figuradamente para una falta menor.', 'Karphos designa un diminuto fragmento seco —una mota de paja, una viruta o una astilla— tan pequeño que podría alojarse inadvertidamente en el ojo de alguien. Jesús lo emplea exclusivamente en su célebre enseñanza sobre la hipocresía al juzgar a otros: «¿Por qué miras la paja en el ojo de tu hermano y no adviertes la viga en el tuyo?» (Mt 7:3-5; Lc 6:41-42). El contraste dramático entre el karphos (paja) y el dokos (viga) hace que la parábola resulte inolvidable. En español, «paja» capta bien la pequeñez del objeto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2596', 'spa', 'Según, conforme a; cada; por, a lo largo de; en; por medio de; hacia; a solas; acerca de; abajo; sobremanera; contra.', 'La preposición más diversa semánticamente del Nuevo Testamento, cuyo sentido originario «abajo» se expandió para abarcar conformidad, distribución, ubicación y oposición. Con 480 apariciones, κατά rige genitivo (movimiento descendente, oposición) y acusativo (norma, distribución, lugar). Su acepción primaria expresa conformidad —«según la ley», «según la carne»— fijando la norma con que algo se mide. Pero también distribuye (diariamente, de casa en casa), sitúa (en la ciudad), señala medio (por linaje), dirección (hacia Cirene) e incluso hostilidad (contra). El despliegue desde el espacial «abajo» hasta el abstracto «según» refleja el desarrollo típico de las preposiciones griegas, de lo concreto a lo metafórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2597', 'spa', 'Bajar, descender; movimiento físico descendente de personas, objetos o manifestaciones divinas.', 'El verbo griego estándar para el movimiento descendente, compuesto de κατά (''abajo'') y βαίνω (''ir''). Describe a Jesús bajando de los montes (Mt 8:1), al Espíritu descendiendo como paloma en el bautismo (Mt 3:16), a la lluvia y las inundaciones cayendo sobre una casa (Mt 7:25, 27) y a los ángeles subiendo y bajando sobre el Hijo del Hombre (Jn 1:51). El verbo también porta peso teológico cuando se aplica al descenso divino: el pan del cielo (Jn 6:33, 41, 50, 51, 58) y la nueva Jerusalén que desciende de Dios (Ap 21:2). En español se traduce como ''bajó'', ''descendió'' o ''cayendo'' según el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2600', 'spa', 'descenso, bajada; un camino o pendiente hacia abajo', 'Este sustantivo denota un descenso, camino cuesta abajo o declive, literalmente, una bajada. En Lucas 19:37, describe la entrada triunfal de Jesús: al acercarse a Jerusalén, «en la bajada (καταβάσει) del Monte de los Olivos», toda la multitud de discípulos comenzó a alabar a Dios. El detalle geográfico sitúa el evento en la ladera oriental del Olivete, donde el camino desciende hacia el valle del Cedrón y la ciudad. La ubicación es significativa: desde este punto, los peregrinos contemplaban por primera vez la vista completa del templo, lo cual naturalmente provocaba celebración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2601', 'spa', 'Hacer descender, hacer bajar; bajar algo o a alguien desde un lugar elevado', 'Verbo causativo que significa hacer que algo o alguien descienda: bajar desde una altura, hacer descender o impulsar hacia abajo. Los autores clásicos lo emplean para bajar a alguien de una pira funeraria, obligar a un ejército a descender a terreno llano o hacer retroceder a los enemigos. En sentido metafórico, significa rebajarse del orgullo a la humildad, o avanzar cronológicamente en una narración. En gramática describe el desplazamiento del acento hacia adelante. El compuesto intensifica el verbo simple «descender» con fuerza causativa: no simplemente bajar, sino hacer que alguien o algo baje.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2602', 'spa', 'Acción de echar o poner un fundamento; se usa para referirse a la fundación del mundo desde la creación, y una vez para el depósito de simiente (conce', 'Acción de echar o poner un fundamento; se usa para referirse a la fundación del mundo desde la creación, y una vez para el depósito de simiente (concepción). Καταβολή lleva la idea raíz de ''echar abajo'' o ''poner fundamento'', y en el Nuevo Testamento aparece abrumadoramente en la frase ἀπὸ καταβολῆς κόσμου — ''desde la fundación del mundo'' — un majestuoso marcador temporal que se remonta al mismísimo inicio de la creación (Mt 13:35, Jn 17:24, Ef 1:4, Ap 13:8). Esta frase enmarca los propósitos soberanos de Dios como establecidos antes de que existiera cosa alguna. Una notable excepción ocurre en Hebreos 11:11, donde la misma palabra describe a Sara recibiendo poder εἰς καταβολὴν σπέρματος — ''para el depósito de simiente'', es decir, la concepción. La evidencia multilingüe refleja esta división: la mayoría de las lenguas usan ''fundación'' (español fundación, alemán Grundlegung, francés fondation), mientras que Hebreos 11:11 atrae ''concepción'' en inglés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2603', 'spa', 'descalificar, privar del premio; juzgar en contra o despojar de la recompensa', 'Este verbo combina ''juzgar'' (βραβεύω) con ''en contra'' (κατά), y significa declarar a alguien indigno de un premio, descalificarlo o despojarlo de su recompensa. En Colosenses 2:18, Pablo advierte: ''Que nadie os descalifique (καταβραβευέτω), insistiendo en el ascetismo y el culto a los ángeles.'' La imagen es atlética: un juez que declara a un competidor inelegible o le niega su premio legítimo. Pablo advierte contra falsos maestros que pretendían declarar insuficientes a los creyentes a menos que adoptaran prácticas ajenas a las Escrituras; esos jueces carecen de autoridad para descalificar a quienes Cristo ya ha declarado justos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2604', 'spa', 'proclamador, anunciador, heraldo; quien proclama o declara públicamente', 'Este sustantivo designa a un proclamador o heraldo, alguien que anuncia o declara algo públicamente. En Hechos 17:18, los filósofos epicúreos y estoicos se encuentran con Pablo en Atenas y preguntan: ''¿Qué querrá decir este palabrero?'' Otros decían: ''Parece ser un proclamador (καταγγελεύς) de divinidades extranjeras'', porque predicaba a Jesús y la resurrección. El término es neutro —un heraldo o anunciador— pero los filósofos lo usan con desdén. Reconocen que Pablo proclama algo, pero malinterpretan su mensaje como politeísta, como si introdujera nuevos dioses.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2605', 'spa', 'Proclamar públicamente, anunciar con autoridad: declarar un mensaje o enseñanza abiertamente ante una audiencia. Katangello es un compuesto de κατά (''', 'Proclamar públicamente, anunciar con autoridad: declarar un mensaje o enseñanza abiertamente ante una audiencia. Katangello es un compuesto de κατά (''hacia abajo, completamente'') y ἀγγέλλω (''anunciar''), que produce un verbo con fuerza de proclamación pública y plena autoridad. Sus 18 apariciones en el Nuevo Testamento se concentran en Hechos y las epístolas paulinas, convirtiéndolo en un término distintivamente misionero y kerigmático. En Hechos, los apóstoles ''proclaman'' la resurrección de Jesús (Hch 4:2), la palabra de Dios en las sinagogas (Hch 13:5) y el perdón de pecados por medio de Cristo (Hch 13:38). Pablo dice a los corintios que cada vez que comen el pan y beben la copa, ''proclaman la muerte del Señor hasta que él venga'' (1 Co 11:26). En Colosenses 1:28 declara: ''A él proclamamos, amonestando y enseñando a todos.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2606', 'spa', 'Reírse de alguien con burla y desprecio; mofarse, ridiculizar, escarnecer con risa desdeñosa', 'Este verbo significa reírse de alguien con desprecio, burlarse o mofarse. Las tres apariciones en el Nuevo Testamento describen a las multitudes ridiculizando a Jesús cuando anunció que una niña muerta solo estaba dormida (Mateo 9:24, Marcos 5:40, Lucas 8:53). Los dolientes profesionales y la gente reunida se rieron con desdén, considerando absurda su afirmación. El uso del imperfecto (κατεγέλων) sugiere una risa sostenida y despectiva. La palabra no expresa simple risa, sino una burla que descarta por completo lo que alguien dice, tratándolo como ridículo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2607', 'spa', 'Condenar, juzgar en contra, censurar; emitir un juicio desfavorable sobre alguien', 'Este verbo significa juzgar desfavorablemente, condenar o censurar a alguien. Pablo lo emplea en Gálatas 2:11 al describir su confrontación con Pedro: lo enfrentó cara a cara porque «estaba condenado» por su hipocresía. Primera de Juan lo usa dos veces respecto a la conciencia: si nuestro corazón nos condena (3:20), Dios es mayor que nuestro corazón; pero si no nos condena (3:21), tenemos confianza ante Dios. El uso neotestamentario abarca tanto la condena objetiva por conducta reprobable como la autocondena subjetiva de la propia conciencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2608', 'spa', 'Quebrar, romper, destrozar; usado para huesos rotos o una cana cascada, implicando fractura violenta.', 'Denota una rotura o quebradura violenta, ya sea de huesos, canas u otros objetos rigidos. Su uso en el Nuevo Testamento abarca tanto la misericordia tierna como la ejecucion brutal. En Mateo 12:20, citando a Isaias, Jesus es el siervo que no quebrara la cana cascada, un retrato de ternura hacia lo fragil. En Juan 19:31-33, los soldados romanos quiebran las piernas de los crucificados para acelerar la muerte, pero encuentran a Jesus ya muerto. El espanol ''quebrar'' captura con precision la violencia de la fractura inherente al termino griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2609', 'spa', 'Conducir o llevar hacia abajo desde un lugar más alto; también náutico: llevar un barco a tierra, atracar en puerto.', 'Compuesto de κατά (abajo) y ἄγω (conducir), este verbo describe el movimiento descendente de personas o embarcaciones. En Hechos aparece repetidamente cuando Pablo es escoltado hacia abajo — de Jerusalén a Cesarea (Hch 9:30; 23:15, 20, 28) o del cuartel al Sanedrín (Hch 22:30). El sentido náutico emerge dos veces durante el viaje de Pablo a Roma: ''atracamos en Sidón'' (Hch 27:3) y ''habiendo atracado en Siracusa'' (Hch 28:12). El español capta bien esta distinción: ''hacer bajar'' o ''llevar'' para conducir a una persona hacia abajo, pero ''atracar'' para las llegadas marítimas, un término técnico que confirma el registro semántico diferenciado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2610', 'spa', 'conquistar, vencer, someter; prevalecer contra un adversario en la lucha', 'Este verbo significa prevalecer contra alguien, vencer en una lucha o conquistar. En Hebreos 11:33 describe las hazañas de los santos del Antiguo Testamento: por la fe ''conquistaron (κατηγωνίσαντο) reinos, hicieron justicia, alcanzaron promesas.'' El verbo aparece en contexto de batalla o contienda, denotando una victoria decisiva sobre la oposición. La fe permitió a jueces como Gedeón y a reyes como David vencer enemigos militarmente superiores, no por su propia fuerza sino confiando en el Dios que pelea por su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2611', 'spa', 'vendar, atar una herida; envolver o curar una lesión con vendajes', 'Este verbo significa vendar o atar heridas, es decir, envolver o curar lesiones para promover la sanación. En Lucas 10:34, el buen samaritano ''vendó (κατέδησεν) sus heridas, echándoles aceite y vino.'' La acción muestra cuidado médico práctico: el samaritano limpió las heridas con vino como antiséptico, las alivió con aceite y las vendó para protegerlas y facilitar la curación. El verbo aparece en contextos de atención compasiva hacia los heridos, tratando lesiones para restaurar la salud y la integridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2612', 'spa', 'evidente, manifiesto; claramente visible o conocido', 'Este adjetivo describe algo que se ha vuelto completamente claro e innegable. En Hebreos 7:15 introduce el cambio evidente en el sacerdocio bajo Cristo, donde la transición del orden levítico al de Melquisedec es tan obvia que no requiere argumento. Las glosas multilingues (evidente, manifiesto, manifeste, offenbar) enfatizan la naturaleza pública e inconfundible de lo que se revela. El uso clásico muestra que la palabra se aplicaba a cosas descubiertas o conocidas mediante la observación directa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2613', 'spa', 'Condenar, declarar culpable, dictar sentencia judicial contra alguien.', 'Katadikazo es un término jurídico que significa pronunciar un veredicto adverso contra una persona, condenarla o dictar sentencia. En el NT, Jesús lo utiliza con fuerza tanto como advertencia como invitación: «por tus palabras serás condenado» (Mt 12:37) y «no condenéis y no seréis condenados» (Lc 6:37). También desafía a los fariseos diciéndoles que, si hubieran comprendido la misericordia, no habrían condenado a los inocentes (Mt 12:7). Los acusadores de Pablo ante Festo buscan un veredicto formal de condena (Hch 25:15). El prefijo κατα- intensifica la idea básica de juzgar, confiriéndole la fuerza de un fallo adverso decisivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2614', 'spa', 'perseguir de cerca, buscar con empeño, seguir con determinación', 'Este verbo compuesto intensifica el simple «perseguir» mediante un prefijo que indica acción exhaustiva o dirigida. En Marcos 1:36, los discípulos buscan a Jesús con urgencia después de que él se retiró a orar: literalmente lo «rastrearon». El griego clásico emplea este término para la persecución militar implacable y, en sentido figurado, para ir tras una meta con decisión. Su única aparición en el Nuevo Testamento subraya la determinación y premura con que los discípulos salieron a encontrarlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2617', 'spa', 'Avergonzar, deshonrar; en voz pasiva, ser avergonzado o defraudado en la propia confianza. El verbo καταισχύνω lleva la fuerza de avergonzar o deshonr', 'Avergonzar, deshonrar; en voz pasiva, ser avergonzado o defraudado en la propia confianza. El verbo καταισχύνω lleva la fuerza de avergonzar o deshonrar a alguien, con una distinción crucial entre activa y pasiva que recorre sus usos en el NT. En voz activa, Dios emplea la vergüenza como arma de inversión: «Dios escogió lo necio del mundo para avergonzar a los sabios» (1 Co 1:27). En voz pasiva, describe la experiencia de ser avergonzado o, más precisamente, de ver vindicada o no la propia confianza, como en la gran promesa de Ro 9:33 y 10:11: «todo el que cree en él no será avergonzado». El español capta ambos polos vívidamente: avergüence (vergüenza activa) frente a eran avergonzados (experiencia pasiva).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2618', 'spa', 'Quemar por completo o consumir con fuego, ya sea encendiendo activamente o siendo consumido pasivamente en llamas. Κατακαίω intensifica el verbo básic', 'Quemar por completo o consumir con fuego, ya sea encendiendo activamente o siendo consumido pasivamente en llamas. Κατακαίω intensifica el verbo básico «quemar» con el prefijo κατα-, indicando combustión total y completa. Juan el Bautista advierte que el que viene «quemará la paja con fuego que nunca se apagará» (Mt 3:12; Lc 3:17), y la parábola de Jesús instruye a los siervos a «juntar la cizaña y quemarla» (Mt 13:30). En voz pasiva, la imaginería apocalíptica de Apocalipsis describe cómo la tercera parte de la tierra fue quemada (Ap 8:7) y Babilonia consumida en llamas (Ap 18:8). El español distingue el activo «quemará» del pasivo «fue quemada».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2619', 'spa', 'Cubrir, velar; cubrirse la cabeza, especialmente en el contexto del culto', 'Este verbo significa cubrir o velar, y aparece tres veces en 1 Corintios 11 dentro de la compleja discusión de Pablo sobre el uso de velo en el culto. En el versículo 6, Pablo argumenta que si la mujer no se cubre la cabeza, debería cortarse el cabello; pero si cortárselo es vergonzoso, que se cubra. En el versículo 7 afirma que el varón no debe cubrirse la cabeza, pues es imagen y gloria de Dios. Pablo aborda la cuestión cultural y teológica del velo en la adoración cristiana, con argumentos basados en el orden de la creación, los ángeles y la naturaleza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2620', 'spa', 'Jactarse contra, gloriarse sobre, o triunfar sobre alguien; gloriarse con aire de superioridad.', 'Verbo compuesto que combina ''contra/sobre'' (κατά) con ''gloriarse'' (καυχάομαι), transmitiendo no solo orgullo sino una jactancia dirigida y competitiva: gloriarse contra o por encima de alguien. Pablo advierte a los creyentes gentiles que no se jacten contra las ramas naturales del olivo (Rom 11:18), mientras Santiago declara que la misericordia triunfa sobre el juicio (Stg 2:13), empleando el mismo verbo para mostrar la superioridad confiada de la misericordia. El prefijo κατά anade una fuerza adversativa que distingue este verbo de la jactancia ordinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2621', 'spa', 'Yacer, estar acostado, especialmente de enfermos o postrados en cama; también reclinarse a la mesa en la postura antigua de comer.', 'Yacer, estar acostado, especialmente de enfermos o postrados en cama; también reclinarse a la mesa en la postura antigua de comer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2624', 'spa', 'repartir como herencia, distribuir por sorteo', 'Este verbo técnico compuesto describe la acción de asignar tierras o propiedades como posesión permanente, generalmente por decreto divino o mediante sorteo. En Hechos 13:19, Pablo recuerda cómo Dios repartió la tierra de Canaán entre las tribus de Israel tras destruir siete naciones. El término combina las ideas de «a lo largo de» y «sortear», sugiriendo una distribución metódica del territorio. Su único uso neotestamentario evoca la narrativa fundacional del asentamiento de Israel en la tierra prometida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2625', 'spa', 'Hacer reclinarse a la mesa; sentar o acostar a alguien para comer, reflejando la postura antigua de cenar reclinado.', 'Este verbo describe la accion de hacer que alguien se recline, reflejando la costumbre mediterranea antigua de reclinarse durante las comidas en lugar de sentarse erguido. Aparece exclusivamente en los escritos de Lucas: Jesus se reclina a la mesa de un fariseo (Lucas 7:36), ordena a la multitud sentarse en grupos antes del milagro de la multiplicacion (Lucas 9:14-15), aconseja tomar el lugar mas bajo en un banquete (Lucas 14:8) y se reclina con los discipulos de Emaus (Lucas 24:30). Abarca tanto el sentido causativo activo como la postura cultural del comedor antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2626', 'spa', 'inundar, sumergir por diluvio, anegar', 'Este verbo describe la inmersión arrolladora bajo el agua, usado tanto en sentido literal para inundaciones físicas como metafóricamente para ser abrumado por las circunstancias. En 2 Pedro 3:6 se emplea para referirse al diluvio cósmico que destruyó el mundo antiguo en los días de Noé. El participio pasivo perfecto enfatiza que el mundo «fue inundado», es decir, sufrió una sumersión catastrófica. El uso clásico abarca tanto el sentido literal como la extensión metafórica de ser «inundado» por problemas o desgracias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2627', 'spa', 'Un gran diluvio o inundacion catastrofica; especificamente el diluvio de los tiempos de Noe.', 'Se refiere a una inundacion masiva y abrumadora de agua. En el Nuevo Testamento esta palabra aparece exclusivamente en conexion con el relato del diluvio del Genesis, el juicio divino arquetipico mediante el agua. Jesus cita el diluvio como advertencia sobre la naturaleza subita e inesperada de la venida del Hijo del Hombre (Mateo 24:38-39; Lucas 17:27), y Pedro lo recuerda como precedente del juicio de Dios sobre los impios (2 Pedro 2:5). Cada aparicion subraya la escala catastrofica y el proposito judicial divino implicados en el vocablo griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2629', 'spa', 'cortarse, hacerse heridas, lacerarse a sí mismo', 'Este verbo denota cortar o tajar con violencia, empleado en contextos clásicos para descuartizar carne, talar árboles o infligir heridas. En Marcos 5:5, describe la automutilación del endemoniado gadareno con piedras entre los sepulcros. El participio presente indica acción continua y repetida: se cortaba sin cesar. Tal comportamiento señala un tormento psicológico y espiritual extremo. Las fuentes antiguas utilizan el vocablo para masacres militares y laceraciones rituales, ambas involucrando movimientos de corte repetitivos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2630', 'spa', 'despeñar, arrojar desde un precipicio, lanzar de cabeza por un despeñadero', 'Este verbo compuesto denota específicamente la acción de arrojar a alguien o algo por el borde de un precipicio escarpado. En Lucas 4:29, la multitud del pueblo natal de Jesús intenta despeñarlo desde la cima del monte sobre el cual estaba edificada Nazaret. El infinitivo de propósito revela su intención homicida. El uso clásico confirma el sentido técnico: arrojar a cautivos o criminales por un acantilado como forma de ejecución o por furia en combate. Este término poco frecuente describe un modo específico y violento de intento de asesinato.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2631', 'spa', 'Condenación, sentencia condenatoria, veredicto de culpabilidad; el juicio que condena', 'Este sustantivo designa la condenación, el veredicto que declara culpable y la sentencia resultante. Sus tres apariciones están en Romanos, donde Pablo discute la justificación y la condenación. Romanos 5:16 contrasta el don gratuito con la condenación: el juicio tras una sola transgresión trajo condenación, pero la gracia tras muchas transgresiones trajo justificación. Romanos 5:18 establece el paralelo entre una transgresión que condujo a la condenación de todos y un acto de justicia que conduce a la justificación. Romanos 8:1 proclama triunfalmente: «Ninguna condenación hay para los que están en Cristo Jesús.»');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2632', 'spa', 'Condenar, pronunciar juicio en contra: emitir un veredicto judicial de culpabilidad merecedora de castigo. Katakrinō es un verbo judicial que signific', 'Condenar, pronunciar juicio en contra: emitir un veredicto judicial de culpabilidad merecedora de castigo. Katakrinō es un verbo judicial que significa condenar o dictar sentencia, formado por κατά (''hacia abajo, en contra'') y κρίνω (''juzgar''). Sus 18 usos en el Nuevo Testamento implican consistentemente un pronunciamiento formal o autoritativo de culpabilidad. En las predicciones de la pasión, Jesús anuncia que los principales sacerdotes y escribas lo ''condenarán a muerte'' (Mt 20:18; Mc 10:33). Los hombres de Nínive y la reina del Sur ''condenarán a esta generación'' en el juicio (Mt 12:41-42; Lc 11:31-32). El uso teológico de Pablo es fundamental: ''Dios condenó al pecado en la carne'' enviando a su propio Hijo (Ro 8:3). Hebreos 11:7 dice que la obediencia de Noé ''condenó al mundo.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2634', 'spa', 'Ejercer dominio absoluto sobre alguien; ensenorearse, dominar o someter por la fuerza.', 'Un verbo compuesto enérgico (κατά + κυριεύω) que significa dominar o ensenorearse de alguien, intensificando el verbo base ''gobernar'' con el prefijo κατά (''sobre, encima de''). Jesus contrasta explicitamente a los gobernantes gentiles que se enseñorean de sus subditos con el liderazgo de servicio esperado entre sus seguidores (Mateo 20:25; Marcos 10:42). Pedro repite esta advertencia a los ancianos para que no se enseñoreen de quienes les han sido encomendados (1 Pedro 5:3). De manera llamativa, en Hechos 19:16 el mismo verbo describe a un endemoniado que somete fisicamente a los hijos de Esceva, revelando la fuerza bruta incorporada en la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2635', 'spa', 'Hablar mal de alguien, calumniar o difamar con palabras maliciosas, especialmente dentro de la comunidad de fe.', 'Se refiere a un discurso hostil y denigrante dirigido contra otra persona: hablar en contra de alguien, no simplemente hablar de el. Santiago lo usa tres veces en un solo versiculo (Santiago 4:11) para advertir a los creyentes contra la calumnia mutua, mientras que Pedro lo aplica a los de afuera que difaman a la comunidad cristiana (1 Pedro 2:12; 3:16). En cada aparicion neotestamentaria la palabra conlleva una fuerte censura moral, tratando tal discurso como una violacion de la ley real del amor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2637', 'spa', 'calumniador, persona que habla maliciosamente contra la reputación de otro', 'Este sustantivo designa a una persona que se dedica habitualmente a la difamación y la maledicencia. En Romanos 1:30, Pablo incluye a los «calumniadores» en su catálogo de vicios que caracterizan a la humanidad bajo la ira divina. La palabra combina «contra» con «hablar», subrayando un discurso dirigido a destruir la reputación ajena. A diferencia del simple chisme, κατάλαλος sugiere un ataque verbal deliberado y hostil contra el carácter de otra persona. Este sustantivo agentivo define a alguien por su vicio característico de hablar mal de los demás.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2638', 'spa', 'Asir, alcanzar o comprender; agarrar física, mental o espiritualmente, sorprender a alguien en el acto o alcanzar una meta.', 'Asir, alcanzar o comprender; agarrar física, mental o espiritualmente, sorprender a alguien en el acto o alcanzar una meta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2639', 'spa', 'inscribir, registrar en una lista o catálogo oficial', 'Este verbo significa inscribir en un registro o lista oficial, utilizado para el empadronamiento en documentos públicos. En 1 Timoteo 5:9, se instruye que una viuda puede «ser inscrita» (imperativo pasivo) en la lista de apoyo de la iglesia solo si cumple ciertos requisitos. El uso clásico muestra esta palabra en listas militares, registros cívicos y relatos detallados. La voz pasiva enfatiza una acción oficial: ella debe ser colocada en la lista por la iglesia. Este término técnico refleja las prácticas organizativas del cristianismo primitivo para el sustento de las viudas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2640', 'spa', 'remanente, lo que queda; la porción que sobrevive tras la pérdida o destrucción', 'Sustantivo neutro que designa el remanente o lo que permanece después de una pérdida, destrucción o consumo. La Septuaginta lo emplea para traducir términos hebreos referidos al remanente sobreviviente de Israel: aquellos que escapan del juicio o regresan del exilio. Los profetas desarrollan ampliamente la teología del remanente: Dios preserva a unos pocos fieles a través de la catástrofe. Pablo aplica este concepto a la salvación de un remanente de Israel conforme a la gracia. La palabra subraya lo que sobrevive cuando la mayor parte se ha perdido, una pequeña porción portadora de esperanza y continuidad. Algunos manuscritos presentan confusión con κατάλημμα, un término emparentado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2641', 'spa', 'Dejar atrás, abandonar; en voz pasiva, permanecer; reservar o apartar para un propósito.', 'Dejar atrás, abandonar; en voz pasiva, permanecer; reservar o apartar para un propósito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2642', 'spa', 'apedrear, ejecutar lanzando piedras hasta causar la muerte', 'Este verbo denota el acto específico de matar a alguien arrojándole piedras, el método de ejecución prescrito para ciertos delitos bajo la ley mosaica. En Lucas 20:6, los principales sacerdotes expresan su temor de que la multitud «nos apedreará» si niegan la autoridad divina de Juan el Bautista. El futuro indicativo revela su certeza sobre la violencia popular. El griego clásico y bíblico emplea este compuesto tanto para la ejecución formal como para ataques espontáneos de la turba. La única aparición neotestamentaria muestra cómo los líderes religiosos calculaban la reacción popular para protegerse de la ira justa del pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2643', 'spa', 'Reconciliacion; la restauracion de una relacion rota, especialmente entre Dios y la humanidad.', 'Denota el cambio dramatico de la enemistad a la amistad, de la alienacion a la relacion restaurada. En la teologia de Pablo, es una iniciativa de Dios: mientras eramos enemigos, Dios nos reconcilio consigo mismo por medio de Cristo (Romanos 5:11). La palabra lleva ricos matices de su uso secular griego en la diplomacia y el cambio monetario: una transaccion costosa que restaura el valor apropiado. Pablo habla tanto del don personal de la reconciliacion (2 Corintios 5:18-19) como de su alcance cosmico, ya que el rechazo de Israel significo reconciliacion para el mundo (Romanos 11:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2644', 'spa', 'Reconciliar, restaurar de la enemistad a la amistad; término clave paulino para la obra salvífica de Dios en Cristo.', 'Katallasso es una de las grandes palabras teológicas del NT; significa transformar una relación de hostilidad en armonía. Pablo lo utiliza para describir el corazón del evangelio: cuando aún éramos enemigos, Dios nos reconcilió consigo mismo mediante la muerte de su Hijo (Ro 5:10). En 2 Corintios 5:18-19, Dios es quien «nos reconcilió consigo mismo por medio de Cristo» y encomendó a los creyentes «el ministerio de la reconciliación». La palabra también aparece en la instrucción práctica para que una esposa separada se reconcilie con su marido (1 Co 7:11). Expresa el movimiento del distanciamiento a la relación restaurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2645', 'spa', 'restante, lo que queda, el resto o remanente', 'Este adjetivo describe lo que queda después de que otros han sido apartados, frecuentemente con peso teológico como «el remanente». En Hechos 15:17 se cita Amos 9:12, refiriéndose a «el resto de la humanidad» que buscará al Señor tras la restauración de la tienda caída de David. El adjetivo plural funciona como sustantivo: «los que quedan». El uso clásico lo emplea para sobrevivientes de batalla, recursos sobrantes o la opción restante. La cita de Santiago reinterpreta la teología del remanente de Israel para incluir a los gentiles dentro del pueblo restaurado de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2646', 'spa', 'Alojamiento, posada, aposento de huéspedes; hospedaje temporal para viajeros', 'Este sustantivo designa un lugar de alojamiento, ya sea una posada pública o un aposento para huéspedes. Lucas 2:7 relata célebremente que no había lugar para ellos «en el mesón» cuando nació Jesús. Marcos 14:14 y Lucas 22:11 recogen las instrucciones de Jesús para preparar la Pascua: «¿Dónde está el aposento?», refiriéndose al aposento alto donde se celebró la Última Cena. El uso neotestamentario abarca tanto el hospedaje público negado a María y José como la habitación privada dispuesta para la última Pascua de Jesús. La palabra sugiere alojamiento temporal, no residencia permanente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2647', 'spa', 'Derribar o demoler; abolir o anular; alojarse o encontrar hospedaje al final de un viaje. Un verbo griego cuyo alcance semántico se extiende desde la ', 'Derribar o demoler; abolir o anular; alojarse o encontrar hospedaje al final de un viaje. Un verbo griego cuyo alcance semántico se extiende desde la demolición física hasta la hospitalidad pacífica. En su uso primario, καταλύω significa derribar o desmantelar una estructura, como cuando Jesús predijo la destrucción del Templo (Mt 24:2, Mc 13:2). Por extensión adquiere la fuerza figurada de abolir o anular, como en la célebre declaración ''No he venido a abolir la Ley'' (Mt 5:17). El sorprendente tercer sentido, ''hospedarse'', surge de la imagen de desuncir a los animales al final del día, visible en Lucas 19:7 cuando Zaqueo recibe a Jesús como huésped.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2648', 'spa', 'observar detenidamente, considerar con atención, estudiar cuidadosamente', 'Este verbo compuesto intensifica «aprender» o «percibir» con un prefijo que sugiere minuciosidad: aprender mediante la observación atenta. En Mateo 6:28, Jesús lo emplea al ordenar «observad los lirios del campo», invitando a un estudio detenido de cómo Dios viste las flores silvestres. El imperativo aoristo exige un enfoque mental deliberado. El uso clásico muestra esta palabra para inspección cuidadosa, percepción y aprendizaje mediante examen. La única aparición bíblica modela la atención contemplativa hacia la creación como antídoto contra la ansiedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2649', 'spa', 'Testificar en contra de alguien, dar testimonio adverso, declarar como testigo contra un acusado', 'Este verbo significa dar testimonio o declarar en contra de alguien, especialmente en un contexto judicial. Aparece en las escenas del juicio de Jesús. En Mateo 26:62 el sumo sacerdote pregunta: «¿No respondes nada a lo que estos testifican contra ti?» En Mateo 27:13 Pilato le dice: «¿No oyes cuántas cosas testifican contra ti?» Marcos 14:60 ofrece un paralelo. El uso neotestamentario es consistentemente forense: testimonio dado contra un acusado en un proceso judicial, con la ironía de que Jesús guardó silencio ante las acusaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2650', 'spa', 'permanecer, quedarse, continuar en un lugar o estado', 'Este verbo significa quedarse o continuar en un lugar o condición, con énfasis en la persistencia. Hechos 1:13 describe a los apóstoles ''permaneciendo'' en el aposento alto tras la ascensión, donde se dedicaban a la oración. El participio presente sugiere residencia continua durante este período de transición. El griego clásico emplea la palabra tanto para permanecer en un lugar como para mantenerse en un estado o función. Los testimonios multilingües subrayan el aspecto durativo: quedarse, permanecer, persistir. Este único uso neotestamentario captura a la comunidad en espera entre la partida de Jesús y la venida del Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2651', 'spa', 'a solas, aparte, en privado (adverbio); mejor entendido como κατὰ μόνας (en soledad)', 'Adverbio que significa «a solas» o «aparte», aunque gramaticalmente se analiza mejor como la frase κατὰ μόνας («conforme a estar solo»). Describe situaciones en las que alguien actúa o habla en privado, lejos de los demás. Jesús se retiraba κατὰ μόνας con frecuencia para orar, y los discípulos le preguntaban cuando estaban a solas con él. La expresión captura una soledad intencional: no un aislamiento accidental, sino una privacidad escogida para la oración, la enseñanza o el descanso. El griego clásico y bíblico la usa para apartar escenas de la actividad pública, creando un espacio de revelación íntima o encuentro personal con Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2652', 'spa', 'maldición, cosa bajo anatema divino, objeto consagrado a la destrucción', 'Este sustantivo designa algo consagrado a la destrucción, puesto bajo maldición solemne. Apocalipsis 22:3 declara que en la nueva creación ''no habrá más maldición'': nada maldito existirá allí. La palabra intensifica el simple ''anatema'' mediante un prefijo. El uso clásico y en la Septuaginta la aplica a cosas consagradas a la destrucción, ya sean ofrendas paganas u objetos bajo interdicto divino. Todos los testimonios de traducción convergen en ''maldición''. La promesa escatológica revierte la maldición introducida en la caída, restaurando la presencia divina sin mediación, sin separación ni juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2653', 'spa', 'maldecir, proferir una maldición, invocar destrucción', 'Este verbo significa invocar una maldición sobre alguien, pidiendo el juicio divino o comprometiéndose bajo juramento. Mateo 26:74 describe a Pedro que ''comenzó a maldecir'' al negar conocer a Jesús, ya sea maldiciendo a sí mismo si mentía o maldiciendo a Jesús para demostrar su desvinculación. El infinitivo sigue a ''comenzó'', indicando el inicio de juramentos cada vez más desesperados. Esta forma verbal se relaciona con el sustantivo ''maldición'' (G2652). Los testimonios multilingües muestran ''maldecir/curse/maudire'', subrayando el acto verbal de pronunciamiento. La maldición de Pedro marca el punto más bajo de su negación, justo antes del canto del gallo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2654', 'spa', 'consumir, devorar, destruir por completo', 'Este verbo describe la consumición total, especialmente por fuego. Hebreos 12:29 declara que ''nuestro Dios es fuego consumidor'', usando el participio presente para enfatizar un poder activo y continuo. El uso clásico muestra la palabra para agotar recursos, devorar combustible o comer por completo. El compuesto intensifica el simple ''consumir'' mediante un prefijo de totalidad. Todos los testimonios de traducción preservan la imagen de devorar o consumir. La cita de Hebreos adapta Deuteronomio 4:24, advirtiendo que la santidad divina quema todo lo impuro. El participio caracteriza la naturaleza esencial de Dios como fuego santo que no tolera el pecado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2655', 'spa', 'Ser una carga para alguien, gravar, pesar sobre otro; imponerle un peso o una obligación onerosa', 'Este verbo significa ser una carga para alguien, pesar sobre él o imponerle una obligación gravosa. Las tres apariciones se encuentran en 2 Corintios, donde Pablo defiende su independencia económica. En 11:9 y 12:13 insiste en que no fue carga para los corintios: no exigió sustento. En 12:14 declara que tampoco lo será en su próxima visita, porque los busca a ellos, no sus bienes. Pablo emplea el término para describir la carga financiera que rehusó imponer, manteniendo su derecho apostólico pero eligiendo no ejercerlo por amor al evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2656', 'spa', 'hacer señas, indicar con gestos, llamar con un ademán', 'Este verbo significa comunicarse mediante gestos, especialmente con movimientos de cabeza o ademanes. Lucas 5:7 describe a los pescadores que ''hicieron señas'' a sus compañeros en la otra barca para que vinieran a ayudar con la pesca milagrosa. El aoristo indica un momento decisivo cuando se dieron cuenta de que no podían manejar solos la abundancia. El uso clásico muestra la palabra para asentir con la cabeza, llamar con gestos o hacer cualquier señal con la mano o la cabeza. Los testimonios multilingües subrayan la comunicación no verbal. Esta única aparición bíblica captura la urgencia silenciosa de pescadores abrumados por la captura, donde el gesto basta cuando se necesita ayuda inmediata.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2657', 'spa', 'Observar atentamente, considerar con cuidado o percibir con discernimiento; fijar la mente en algo para comprenderlo.', 'Observar atentamente, considerar con cuidado o percibir con discernimiento; fijar la mente en algo para comprenderlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2658', 'spa', 'Llegar a un destino, arribar; en sentido figurado, alcanzar una meta, un estado o la madurez espiritual.', 'Llegar a un destino, arribar; en sentido figurado, alcanzar una meta, un estado o la madurez espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2659', 'spa', 'estupor, embotamiento, entumecimiento del espíritu', 'Este sustantivo designa un estado de estupefacción mental o espiritual, una incapacidad para percibir o responder. En Romanos 11:8, Pablo cita a Isaías sobre cómo Dios dio a Israel «un espíritu de estupor», un endurecimiento judicial que impide ver y oír. El genitivo indica la cualidad del espíritu otorgado. El uso clásico y de la Septuaginta refleja desconcierto, estupefacción o el entumecimiento posterior a una conmoción. El uso cristiano posterior lo extiende a la compunción. Los testimonios multilingües (stupor, estupor, assoupissement, Betäubung) subrayan el estado de insensibilidad embotada. Pablo lo emplea para explicar la ceguera temporal de Israel respecto al evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2660', 'spa', 'traspasar, punzar, herir profundamente, compungir', 'Este verbo significa traspasar o punzar, usado literalmente para heridas físicas y metafóricamente para un impacto emocional profundo. En Hechos 2:37, la multitud de Pentecostés fue «traspasada en el corazón» por el sermón de Pedro acerca de la crucifixión del Mesías. El aoristo pasivo indica que recibieron un golpe súbito y doloroso en la conciencia. La Septuaginta emplea este término para expresar conmoción o desconcierto. El español «fueron compungidos» y el alemán «fueron traspasados» captan el impacto cortante y lacerante. Este traspasamiento cognitivo y emocional produce la pregunta urgente: «¿Qué haremos?»');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2661', 'spa', 'Considerar digno, juzgar merecedor, estimar que alguien es digno de algo', 'Este verbo significa considerar a alguien digno, juzgarlo merecedor o estimarlo como apto para algo. Lucas 20:35 describe a «los que son tenidos por dignos de alcanzar aquel siglo y la resurrección de los muertos». Hechos 5:41 relata que los apóstoles se regocijaron «de haber sido tenidos por dignos de padecer afrenta por el Nombre». 2 Tesalonicenses 1:5 cita la perseverancia de los tesalonicenses como evidencia de «que seáis tenidos por dignos del reino de Dios». El uso neotestamentario involucra consistentemente el juicio divino de dignidad para la bendición escatológica o el sufrimiento presente por causa de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2662', 'spa', 'Pisotear, hollar con los pies; literal (aplastar pisando) o figurado (tratar con desprecio o desdén).', 'Describe el acto violento de pisar o aplastar algo bajo los pies. Jesús lo emplea literalmente al hablar de la semilla que cae en el camino y es pisoteada (Lc 8:5) y de la sal que se echa fuera y la pisan los transeúntes (Mt 5:13), pero también figuradamente al advertir contra echar perlas a los cerdos que las pisotean (Mt 7:6). El uso teológicamente más intenso aparece en Hebreos 10:29, donde rechazar a Cristo se describe como pisotear al Hijo de Dios — una imagen de profanación despectiva que el español ''pisotear'' captura con toda su fuerza visceral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2663', 'spa', 'Reposo, lugar o estado de descanso — el cese prometido por Dios del trabajo, el descanso sabático escatológico ofrecido a su pueblo.', 'Katapausis aparece nueve veces en el NT, ocho de ellas concentradas en Hebreos 3-4, donde el autor desarrolla uno de los argumentos teológicos más sostenidos sobre el reposo en toda la Biblia. Apoyándose en el Salmo 95 y el relato de la creación en Génesis, el escritor argumenta que el reposo de Dios — su propia katapausis después de la creación — permanece abierto como promesa para que los creyentes entren en él. La palabra tiene un doble significado: es tanto un lugar de descanso (como en Hch 7:49, citando Is 66:1, ''¿Cuál es el lugar de mi reposo?'') como un estado de cesación del trabajo. La advertencia repetida ''no entrarán en mi reposo'' (He 3:11, 18; 4:3, 5) transforma una metáfora espacial en una realidad espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2664', 'spa', 'Hacer cesar, contener, refrenar (transitivo); reposar o cesar en la actividad (intransitivo).', 'Posee una doble fuerza verbal: en forma transitiva significa detener o impedir que alguien haga algo; en forma intransitiva significa descansar o cesar del trabajo. El autor de Hebreos recurre profundamente al Génesis al señalar que Dios ''reposó'' en el séptimo día (He 4:4) y luego argumenta que Josué no dio a Israel el verdadero reposo (He 4:8), dejando aún disponible un reposo sabático. El creyente que entra en el reposo de Dios ''cesa de sus propias obras'' tal como Dios lo hizo (He 4:10). En Hechos 14:18 aparece el sentido transitivo: Pablo y Bernabé apenas logran contener a la multitud para que no les ofrezca sacrificios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2665', 'spa', 'Cortina, velo; específicamente el velo interior del Templo que separaba el Lugar Santo del Lugar Santísimo.', 'Καταπέτασμα designa una cortina o velo, y en el NT se refiere concretamente al gran velo del Templo de Jerusalén. Los tres evangelios sinópticos registran que este velo se rasgó en dos, de arriba abajo, en el momento de la muerte de Jesús (Mt 27:51; Mr 15:38; Lc 23:45), señal dramática de que el acceso a la presencia de Dios quedaba abierto. La carta a los Hebreos desarrolla esto teológicamente: Jesús entró «dentro del velo» como precursor a nuestro favor (Heb 6:19), y el autor explica el significado de las cortinas exterior e interior del tabernáculo (Heb 9:3; 10:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2666', 'spa', 'Tragar, devorar, abrumar; engullir por completo, usado literal y figuradamente de destrucción o aflicción.', 'Καταπίνω significa tragar o engullir por completo, con una imagen física vívida y una poderosa fuerza metafórica. Jesús lo emplea con mordaz ironía en Mt 23:24: colar el mosquito y tragarse el camello. Pablo lo utiliza triunfalmente: la muerte es «tragada» en victoria (1 Co 15:54), y lo mortal es absorbido por la vida (2 Co 5:4). También puede describir el ser consumido por una tristeza excesiva (2 Co 2:7). Hebreos 11:29 recuerda al Mar Rojo tragando a los egipcios. El término transmite la totalidad violenta del acto de engullir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2667', 'spa', 'Caer, desplomarse, derrumbarse; caer de una posición más alta a una más baja', 'Este verbo significa caer o desplomarse, generalmente desde una posición erguida o elevada. Lucas 8:6 describe la semilla que «cayó» sobre terreno rocoso en la parábola del sembrador. Hechos 26:14 relata el encuentro de Pablo en el camino a Damasco: «todos caímos a tierra». Hechos 28:6 describe a la gente observando a Pablo, esperando que se hinchara o «de repente cayera muerto» tras la mordedura de víbora. Los usos neotestamentarios abarcan lo agrícola (semillas que caen), lo teofánico (caer ante la presencia divina) y lo médico esperado (desplomarse por efecto del veneno).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2668', 'spa', 'navegar hacia tierra, arribar a puerto, llegar por mar', 'Este verbo náutico significa navegar hacia tierra y llegar, generalmente entrando a un puerto. En Lucas 8:26, se registra que Jesús y los discípulos «navegaron hacia» la región de los gadarenos, al otro lado del lago de Galilea. El aoristo indica la llegada completada del viaje. El uso clásico muestra este término específicamente para navegar del mar abierto a la costa, o río abajo hacia un destino. El prefijo «abajo» puede sugerir movimiento hacia la orilla desde aguas más profundas. Todos los testimonios de traducción preservan el contexto marítimo. La única aparición en el Nuevo Testamento prepara el escenario para el encuentro de Jesús con el endemoniado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2671', 'spa', 'Maldición; invocación solemne de juicio divino o daño; usado teológicamente de la maldición de la Ley.', 'Κατάρα es el sustantivo que designa una maldición: una invocación solemne de daño o juicio divino sobre alguien o algo. Pablo hace un uso teológico contundente en Gálatas 3, declarando que todos los que dependen de las obras de la ley están bajo maldición (Gá 3:10), y que Cristo nos redimió de la maldición de la ley al hacerse maldición por nosotros (Gá 3:13). Hebreos advierte que la tierra que produce espinos y abrojos está «próxima a ser maldecida» (Heb 6:8), y Santiago lamenta que la misma lengua produzca bendición y maldición (Stg 3:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2672', 'spa', 'Maldecir; invocar el mal sobre alguien; pronunciar o hacer caer una maldición.', 'Καταράομαι es la contraparte verbal de κατάρα (maldición), y significa invocar maldiciones sobre alguien o pronunciar una imprecación. Jesús ordena una ética radical: «bendecid a los que os maldicen» (Mt 5:44; Lc 6:28), invirtiendo el ciclo esperado de maldición y represalia. Pablo lo repite en Romanos 12:14: «Bendecid y no maldigáis». El término también aparece en la escena dramática en que Jesús maldice la higuera estéril (Mr 11:21) y en el juicio escatológico donde el Rey envía lejos a los malditos (Mt 25:41). El participio perfecto κατηραμένος transmite un estado permanente: «malditos».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2673', 'spa', 'Dejar sin efecto, abolir, anular, destruir; reducir a nada, liberar de una obligación o cortar una relación.', 'Dejar sin efecto, abolir, anular, destruir; reducir a nada, liberar de una obligación o cortar una relación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2674', 'spa', 'contar entre, incluir en el número, considerar como perteneciente a', 'Este verbo significa asignar a alguien a un grupo contándolo entre sus miembros. En Hechos 1:17, el participio perfecto pasivo describe a Judas: «fue contado entre nosotros», habiendo sido oficialmente incluido como uno de los Doce. El tiempo perfecto enfatiza el estado consumado: había sido y permanecía (hasta su traición) parte del grupo apostólico. El uso clásico muestra su empleo para censos o para incluir a alguien en un grupo. La evidencia interlingüística subraya la naturaleza formal y oficial del recuento. El discurso de Pedro reconoce la posición apostólica legítima de Judas antes de su caída.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2675', 'spa', 'Reparar, restaurar, completar o preparar; llevar algo o a alguien a un estado de plena disposición o integridad.', 'Reparar, restaurar, completar o preparar; llevar algo o a alguien a un estado de plena disposición o integridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2676', 'spa', 'restauración, perfeccionamiento, puesta en orden', 'Este sustantivo designa el acto o estado de ser completado, restaurado a su condición apropiada o perfeccionado. En 2 Corintios 13:9, Pablo expresa su oración por la «restauración» o «perfección» de los corintios. La palabra combina el verbo para remendar redes o perfeccionar discípulos con un sufijo nominal. El uso clásico muestra su empleo para la restauración política, la formación o disciplina, o la consumación en general. Los testimonios de traducción divergen (restoration, perfección, Zubereitung/preparación), reflejando el rango semántico que va desde la reparación hasta la completitud y la formación. Pablo desea su plena madurez espiritual e integridad comunitaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2677', 'spa', 'equipamiento, preparación, capacitación para el servicio', 'Este sustantivo se refiere al proceso de preparar o equipar a alguien para una tarea, y está relacionado con el verbo que describe remendar redes o perfeccionar discípulos. En Efesios 4:12, se describen los dones de Cristo — apóstoles, profetas, evangelistas, pastores y maestros — dados «para el perfeccionamiento de los santos para la obra del ministerio». El acusativo indica propósito: estos líderes existen para preparar al pueblo de Dios para el servicio. El uso clásico muestra preparación, provisión o entrenamiento. La palabra implica llevar a las personas a un estado de competencia y disposición. La visión de Pablo contempla el ministerio como vocación de todos los creyentes, donde los líderes funcionan como capacitadores y no como ejecutores exclusivos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2678', 'spa', 'Hacer señas con la mano; gesticular para pedir silencio o captar la atención de una audiencia.', 'Un verbo vívido de gesticulación que describe el acto de agitar o mover la mano para captar la atención del público o pedir silencio. Lucas emplea este verbo cuatro veces en Hechos para retratar a oradores que toman control de la audiencia antes de un discurso importante. Pedro hace señas desde la puerta de la casa de María tras su milagrosa liberación de la prisión (Hch 12:17), Pablo gesticula ante la sinagoga en Antioquía de Pisidia (Hch 13:16), Alejandro intenta hacerse oír ante la turba efesia (Hch 19:33), y Pablo hace señas desde la escalinata de la fortaleza en Jerusalén (Hch 21:40). El español ''hacer señas'' refleja con precisión el gesto físico implícito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2680', 'spa', 'Preparar o disponer; también construir, edificar o erigir una estructura física. Κατασκευάζω significa equipar, acondicionar o dejar algo completament', 'Preparar o disponer; también construir, edificar o erigir una estructura física. Κατασκευάζω significa equipar, acondicionar o dejar algo completamente listo — una palabra que tiende un puente entre la preparación y la construcción. En los Evangelios Sinópticos aparece en la cita de Malaquías 3:1, donde un mensajero ''preparará'' el camino delante del Señor (Mt 11:10, Mr 1:2, Lc 7:27), enfatizando disposición y preparación. Pero en Hebreos el enfoque se traslada a la construcción física: ''toda casa es construida por alguien, pero el constructor de todas las cosas es Dios'' (He 3:3-4). La evidencia multilingüe capta ambas dimensiones — el español distingue preparado de construyéndose, mientras que el alemán usa bauen para ambos, y el francés recurre a préparer de forma generalizada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2681', 'spa', 'Anidar, establecerse, alojarse; dicho de aves que anidan en las ramas, o figuradamente habitar con seguridad.', 'Literalmente significa plantar la tienda o instalarse, pero en el NT aparece de manera más memorable en las parábolas del grano de mostaza, donde las aves vienen y anidan en las ramas del gran arbusto (Mt 13:32; Mc 4:32; Lc 13:19). Esta imagen evoca pasajes veterotestamentarios sobre grandes árboles que dan cobijo a las aves — un símbolo de un reino que ofrece refugio. En Hechos 2:26, Pedro cita el Salmo 16, donde la carne del salmista ''habitará segura'', extendiendo la metáfora del ave que halla refugio al creyente que descansa bajo la protección de Dios. La raíz griega σκηνή (tienda) subyace a toda la palabra, preservando la imagen de quien encuentra morada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2683', 'spa', 'hacer sombra, cubrir con sombra, oscurecer', 'Este verbo significa proyectar una sombra sobre algo, proporcionando cobijo o cobertura. En Hebreos 9:5 se describe a los querubines de gloria «cubriendo con su sombra» el propiciatorio en el tabernáculo. El participio presente sugiere una acción continua de cobertura. El uso clásico muestra la idea de extender toldos, cubrir con sombra o, metafóricamente, oscurecer. Los testimonios interlingüísticos preservan la imagen de sombra y cobertura. En el tabernáculo, las alas de los querubines se extendían sobre la cubierta del arca donde se rociaba la sangre, y su sombra señalaba la presencia divina. Este mismo verbo describe la acción del Espíritu al cubrir a María en la encarnación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2684', 'spa', 'espiar, explorar secretamente, investigar con sigilo', 'Este verbo significa observar detenidamente con fines de inteligencia, ya sea reconocimiento militar o espionaje. En Gálatas 2:4, Pablo describe a «falsos hermanos» que «se infiltraron para espiar nuestra libertad en Cristo Jesús». El infinitivo aoristo expresa su propósito hostil: investigación secreta con intención de socavar. El uso clásico confirma el sentido militar de explorar territorio enemigo. Los testimonios de traducción preservan uniformemente la imagen de espionaje. Pablo presenta a estos infiltrados como agentes de reconocimiento del partido de la circuncisión, recopilando información para lanzar ataques contra la libertad del evangelio. Su investigación no es indagación honesta, sino vigilancia hostil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2685', 'spa', 'espía, explorador, agente secreto', 'Este sustantivo designa a una persona que realiza reconocimiento, ya sea un explorador militar o un agente secreto. En Hebreos 11:31 se menciona a Rahab que recibió «a los espías» en paz, refiriéndose a los exploradores israelitas enviados a reconocer Jericó. El acusativo plural indica que ella acogió a varios agentes. El uso clásico confirma el contexto militar de personal de reconocimiento. Todos los testimonios de traducción preservan la terminología de espionaje. La referencia corresponde a Josué 2, donde Rahab escondió a los espías hebreos de los hombres del rey. Su hospitalidad motivada por la fe hacia agentes enemigos aseguró su salvación cuando Jericó cayó.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2686', 'spa', 'actuar con astucia, engañar con artimañas, explotar mediante argucias', 'Este verbo en voz media significa usar sofismas o astucia para obtener ventaja sobre alguien, vencer mediante manipulación ingeniosa. En Hechos 7:19, se describe al faraón que «actuó con astucia contra nuestros padres», explotando a Israel mediante trabajos forzados e infanticidio. El participio aoristo sugiere una acción deliberada y calculada. El uso clásico muestra la idea de vencer mediante argumentos falaces o evadir con subterfugios. Los testimonios interlingüísticos enfatizan la astucia y la argucia. El discurso de Esteban identifica esta opresión egipcia como una política calculada y malintencionada, no mera gobernanza severa. El «actuar con astucia» incluye tanto la exposición forzada de los niños como la explotación sistemática.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2688', 'spa', 'porte, conducta, manera de comportarse', 'Este sustantivo designa el porte, la conducta o la manera habitual de presentarse ante los demás. En Titus 2:3 se instruye a las mujeres mayores a ser reverentes ''en su porte'', es decir, que todo su comportamiento visible refleje santidad. El dativo indica la esfera en la cual se manifiesta la reverencia. El uso clásico abarca desde la condición física o mental hasta el estado general de las cosas y el comportamiento personal. Los testimonios interlingüísticos varían (demeanor, comportamiento, Haltung), pero convergen en la conducta observable. Pablo imagina un estilo de vida donde la piedad permea el comportamiento visible y la manera característica de vivir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2689', 'spa', 'vestimenta, atuendo, vestido decoroso', 'Este sustantivo se refiere a la ropa o indumentaria, con matices de modestia o decoro en el vestir. En 1 Timothy 2:9 se instruye a las mujeres a adornarse con ''vestimenta decorosa'', con pudor y sobriedad. El dativo indica la manera en que deben presentarse. El uso clásico abarca equipo, vestido y también los significados de modestia o mesura. Algunos testimonios traducen como ropa (vestido, Kleidung), otros enfatizan el aspecto de recato. El contexto contrasta la sencillez apropiada con peinados costosos, oro, perlas y vestidos suntuosos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2691', 'spa', 'dejarse llevar por la sensualidad contra, volverse licencioso en detrimento de, abandonar la devoción', 'Este verbo describe el apartarse de un compromiso por causa de la indulgencia sensual o el deseo de placeres. En 1 Timothy 5:11 se advierte sobre las viudas más jóvenes que, cuando sus pasiones las apartan de Cristo, ''se vuelven sensuales contra'' él, deseando casarse. El subjuntivo aoristo sigue a ''cuando'', indicando un peligro potencial. El compuesto sugiere un volverse en contra por medio de la sensualidad. Los testimonios de traducción luchan por captar este matiz. La preocupación no es el matrimonio en sí, sino el abandono de la devoción a Cristo por causa de deseos descontrolados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2693', 'spa', 'derribar, abatir, postrar en el suelo', 'Este verbo significa postrar, derribar o esparcir por el suelo. En 1 Corinthians 10:5 se declara que Dios no se agradó de la mayoría de la generación del desierto, ''pues fueron derribados en el desierto''. El aoristo pasivo indica que recibieron la acción: Dios los abatió. El uso clásico muestra extender una cama, quedar cubierto de cadáveres (pasivo) o abatir en juicio. Todos los testimonios de traducción preservan la imagen de derrota violenta. Pablo hace referencia a los múltiples juicios en Numbers-Deuteronomy donde los rebeldes israelitas murieron en el desierto, sus cuerpos literalmente esparcidos por la tierra árida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2694', 'spa', 'arrastrar, tirar por la fuerza, llevar a rastras', 'Este verbo significa arrastrar o tirar de algo o alguien por la fuerza. En Luke 12:58 se advierte sobre un adversario que podría ''arrastrarte'' ante el juez si no llegas a un acuerdo en el camino. El subjuntivo aoristo sigue una cláusula de propósito negativo: para que no te arrastre. El uso clásico muestra tirar hacia abajo, jalar violentamente, arrebatar o llevarse cautivos a rastras. Los testimonios interlingüísticos preservan uniformemente la imagen de arrastre forzoso. El contexto legal sugiere a un acusado renuente llevado físicamente ante el tribunal. Jesús usa esta imagen vívida para exhortar a la reconciliación antes de llegar al punto del proceso legal obligatorio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2695', 'spa', 'degollar, matar, sacrificar como animales', 'Este verbo significa degollar o sacrificar, generalmente aplicado a animales pero también usado para la matanza violenta de personas. En Lucas 19:27, la parábola de las minas concluye con la orden del rey: ''Traed aquí a aquellos enemigos míos que no querían que yo reinase sobre ellos, y degolladlos delante de mí.'' El imperativo aoristo exige una acción inmediata y decisiva. En el uso clásico aparece frecuentemente en aoristo pasivo para indicar ser sacrificado. La conclusión impactante de la parábola refleja el destino de quienes rechazan la autoridad del rey: un juicio tan definitivo como el sacrificio de animales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2696', 'spa', 'sellar, asegurar con sello, cerrar herméticamente', 'Este verbo significa sellar algo de forma segura, haciéndolo inviolable o secreto. Apocalipsis 5:1 describe el rollo ''sellado con siete sellos'' en la mano derecha del que está sentado en el trono. El participio perfecto pasivo enfatiza el estado completado: permanece sellado, asegurado contra toda apertura. En el uso clásico se aplicaba a sellar documentos, asegurar bienes o proteger propiedades. En la práctica antigua, múltiples sellos indicaban máxima seguridad y autenticidad. La visión de Juan presenta un rollo cuyo contenido permanece inaccesible hasta que el Cordero demuestra ser digno de romper los sellos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2699', 'spa', 'mutilación, cortadura, falsa circuncisión', 'Este sustantivo significa literalmente una cortadura o incisión, pero en Filipenses 3:2 Pablo lo usa como un juego de palabras despectivo para referirse a la falsa circuncisión. Pablo advierte: ''Guardaos de los mutiladores del cuerpo'', empleando κατατομή (cortadura) como un retruécano despreciativo de περιτομή (circuncisión). En el uso clásico designaba muescas, surcos o incisiones, y técnicamente se refería a la mutilación en oposición a la circuncisión legítima. Al llamar ''mutilación'' a los defensores de la circuncisión, Pablo niega que su práctica tenga valor como pacto: es mera cortadura carnal, no la verdadera marca del pueblo de Dios, que ahora es la circuncisión del corazón por el Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2700', 'spa', 'abatir a flechazos, matar con arco; atravesar con proyectiles', 'Verbo compuesto que significa derribar a alguien con flechas, matar o herir mediante armas arrojadizas. El prefijo κατα- añade fuerza descendente o sentido de acción consumada al acto de disparar. Los textos clásicos lo emplean para muertes en el campo de batalla y en la caza. En voz pasiva significa «ser abatido» o alcanzado por flechas. En contextos bíblicos y de la Septuaginta puede aparecer en descripciones de juicio divino (las flechas de Dios) o de derrota militar. La palabra evoca una imagen violenta: no una muerte abstracta, sino la brutalidad concreta de las flechas alcanzando su objetivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2701', 'spa', 'correr hacia abajo, descender corriendo, acudir apresuradamente', 'Este verbo significa correr hacia abajo o acudir apresuradamente a un lugar, especialmente desde una posición elevada. Hechos 21:32 describe al tribuno romano que, al enterarse del tumulto, ''tomó inmediatamente soldados y centuriones y corrió hacia ellos.'' El aoristo indica una acción rápida y decisiva: se precipitó desde la fortaleza Antonia hacia los atrios del templo. En el uso clásico designaba correr cuesta abajo, desembarcar apresuradamente o la embestida militar contra enemigos. El prefijo ''hacia abajo'' corresponde a la topografía real, ya que la fortaleza dominaba el templo desde arriba. Esta rápida intervención militar salva la vida de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2702', 'spa', 'Abatir, traer contra, emitir (un voto); en voz pasiva, ser vencido o abrumado (especialmente por el sueño).', 'Un verbo compuesto versátil que significa llevar o portar hacia abajo, con aplicaciones que van desde el descenso físico hasta el procedimiento judicial. En Hechos 20:9, el joven Eutico es ''vencido'' por un sueño profundo y cae desde una ventana — la voz pasiva transmite vívidamente cómo fue abrumado por la somnolencia. En Hechos 25:7 y 26:10, el verbo adquiere un sentido judicial: presentar cargos contra alguien o emitir un voto de condena. El español ''siendo vencido'' para el sentido del sueño y ''trayendo'' para el sentido legal ilustran con claridad las dos aplicaciones distintas dentro de un mismo significado raíz de fuerza descendente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2704', 'spa', 'corrompido, depravado, arruinado en la mente', 'Este participio perfecto pasivo funciona como adjetivo y significa corrompido o depravado. En 2 Timoteo 3:8 describe a los adversarios ''corrompidos de entendimiento'' que resisten la verdad, así como Janes y Jambres resistieron a Moisés. El tiempo perfecto enfatiza el estado asentado de corrupción: permanecen en una condición de ruina mental. En el uso clásico significaba destruir, aniquilar o corromper a personas. Pablo ve a estos falsos maestros sumidos en un estado de depravación intelectual y moral que los incapacita para recibir la verdad, con sus mentes arruinadas por el pecado y el error.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2705', 'spa', 'Besar con fervor o afecto; forma intensificada de φιλέω que indica calidez o emoción profunda.', 'Καταφιλέω es una forma intensificada de φιλέω (amar, besar), donde el prefijo κατα- aporta matiz de plenitud, ternura o repetición: besar con fervor, con cariño o repetidamente. Cada aparición en el NT marca un momento de emoción profunda. La mujer pecadora en casa de Simón ''no cesaba de besar'' los pies de Jesús (Luke 7:38, 45). El padre en la parábola del hijo pródigo se echa a su cuello y lo besa (Luke 15:20). Judas emplea este mismo beso ferviente como señal de traición, amarga ironía de que el gesto de mayor afecto se convierta en instrumento de perfidia (Matt 26:49; Mark 14:45). Los ancianos de Éfeso besan a Pablo en una despedida llena de lágrimas (Acts 20:37).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2706', 'spa', 'Despreciar, menospreciar, tratar con desdén — considerar a alguien o algo como indigno de respeto o atención seria.', 'Kataphroneo significa literalmente ''pensar hacia abajo'' (kata + phroneo), y sus nueve apariciones en el NT llevan consistentemente la fuerza de un desdén activo o un desprecio desdeñoso. Jesús advierte contra despreciar a ''uno de estos pequeños'' (Mt 18:10) y enseña que ningún siervo puede servir a dos señores sin despreciar a uno (Mt 6:24; Lc 16:13). Pablo pregunta a los corintios si desprecian la iglesia de Dios (1 Co 11:22) y advierte contra menospreciar la bondad divina (Ro 2:4). La palabra implica no mera indiferencia pasiva sino una devaluación calculada — tratar como indigno lo que merece honra. El español ''despreciar'', el francés ''mépriser'' y el alemán ''verachten'' preservan este fuerte matiz de menosprecio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2707', 'spa', 'despreciador, burlador, el que trata con desprecio', 'Este sustantivo agentivo identifica a alguien caracterizado por el desprecio o la burla. En Hechos 13:41 se cita Habacuc 1:5, advirtiendo: «Mirad, burladores, asombraos y pereced». El vocativo plural se dirige a una categoría de personas: aquellos que habitualmente desprecian. El uso clásico y de la Septuaginta muestra a despreciadores de la ley o de las cosas divinas. El contexto de Habacuc advertía a los israelitas burlones sobre el juicio babilónico; Pablo lo aplica a los burladores judíos del evangelio. No se trata de duda honesta sino de un rechazo arrogante de lo que Dios está haciendo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2709', 'spa', 'subterráneo, debajo de la tierra, del inframundo', 'Este adjetivo describe lo que pertenece al ámbito debajo de la superficie terrestre, a menudo refiriéndose al reino de los muertos o a las divinidades ctónicas. En Filipenses 2:10 se declara que ante el nombre de Jesús toda rodilla se doblará, «en el cielo, en la tierra y debajo de la tierra». El genitivo plural sustantivado se refiere a los seres del ámbito subterráneo. El uso clásico emplea este término para Plutón, los dioses ctónicos y los muertos. La tríada cósmica de Pablo —celestiales, terrestres, subterráneos— abarca todos los ámbitos de la existencia, incluyendo a los muertos, los poderes demoníacos o todo ser infra-terrestre que debe reconocer el señorío de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2711', 'spa', 'refrescar, enfriar, aliviar con frescura', 'Este verbo significa hacer que algo se enfríe, proporcionando alivio mediante el frescor. En Lucas 16:24, el hombre rico en el Hades le suplica a Abraham que envíe a Lázaro «para que moje la punta de su dedo en agua y refresque mi lengua». El subjuntivo aoristo expresa su desesperada petición de alivio. El uso clásico muestra el enfriamiento o refrigeración de cosas, y metafóricamente el apaciguamiento del ardor. La única gota de agua para refrescar la lengua enfatiza tanto el tormento del rico como la imposibilidad de obtener siquiera el más mínimo alivio a través del gran abismo que separa el Hades del seno de Abraham.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2712', 'spa', 'lleno de ídolos, completamente entregado a la idolatría', 'Este adjetivo describe un lugar saturado de ídolos o una persona entregada al culto idolátrico. En Hechos 17:16 se afirma que el espíritu de Pablo se exasperaba al ver que Atenas estaba «llena de ídolos». El acusativo femenino singular concuerda con «la ciudad». Esta palabra poco común, atestiguada principalmente en la literatura cristiana, intensifica el simple «idolátrico» al sugerir una impregnación total. Atenas era famosa por su abundancia de templos, estatuas y santuarios dedicados a diversos dioses, lo cual angustió a Pablo y lo motivó a pronunciar su sermón en el Areópago sobre el Dios desconocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2713', 'spa', 'Enfrente de, delante de; preposición espacial que significa ''directamente frente a'' y se extiende al sentido de ''a la vista de''', 'Preposición compuesta (κατά + ἔναντι, ''abajo contra'') que sitúa algo directamente enfrente o frente a otra cosa. En su sentido espacial, orienta a viajeros y observadores: la aldea ''enfrente'' de vosotros (Mt 21:2; Mr 11:2; Lc 19:30), o Jesús sentado ''enfrente'' del arca de las ofrendas (Mr 12:41) y ''enfrente'' del templo (Mr 13:3). En las epístolas paulinas, el término pasa de la orientación física a la personal: Abraham creyó ''delante'' del Dios que da vida a los muertos (Ro 4:17), y Pablo habla ''delante de Dios en Cristo'' (2 Co 2:17; 12:19). El español capta bien la distinción: ''enfrente de'' para los usos espaciales y ''delante de'' para los teológicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2714', 'spa', 'Delante de, en la presencia de, ante los ojos de; directamente enfrente o cara a cara', 'Esta preposición significa «delante de», «en la presencia de» o «ante los ojos de», con la connotación de estar directamente enfrente de alguien. Efesios 1:4 describe a Dios eligiéndonos «para que fuésemos santos y sin mancha delante de él en amor». Colosenses 1:22 dice que Cristo nos reconcilió «para presentaros santos, sin mancha e irreprensibles delante de él». Judas 24 atribuye a Dios el poder de «presentaros sin mancha ante su presencia gloriosa». Todos los usos neotestamentarios aparecen en contextos doxológicos o teológicos que describen el estar en la presencia directa de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2716', 'spa', 'Llevar a cabo, cumplir, realizar; producir o causar un efecto o resultado.', 'Llevar a cabo, cumplir, realizar; producir o causar un efecto o resultado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2718', 'spa', 'Bajar, descender; moverse de un lugar más alto a uno más bajo.', 'Bajar, descender; moverse de un lugar más alto a uno más bajo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2719', 'spa', 'Devorar, consumir por completo; usado del comer literal, la explotación figurada y la destrucción por fuego o juicio divino.', 'Devorar, consumir por completo; usado del comer literal, la explotación figurada y la destrucción por fuego o juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2720', 'spa', 'Enderezar, dirigir, guiar el camino; conceder éxito o prosperidad', 'Este verbo significa enderezar, dirigir o guiar el camino de alguien, y también puede significar conceder éxito o prosperidad. En Lucas 1:79, Zacarías profetiza que el Mesías vendrá «para encaminar nuestros pies por el camino de paz». En 1 Tesalonicenses 3:11, Pablo ora: «Que nuestro Dios y Padre mismo, y nuestro Señor Jesús, dirijan nuestro camino a vosotros». En 2 Tesalonicenses 3:5 pide: «Que el Señor dirija vuestros corazones al amor de Dios y a la constancia de Cristo». El uso neotestamentario se centra consistentemente en la dirección divina: Dios guiando sendas, dirigiendo viajes y orientando corazones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2721', 'spa', 'levantarse contra, atacar, asaltar a alguien con intención hostil', 'Este término describe una acción hostil coordinada, típicamente cuando un grupo se levanta contra alguien en oposición o violencia. En Hechos 18:12, Pablo experimenta esto cuando los judíos se levantan unánimemente contra él ante el tribunal de Galión. Las traducciones al español y al francés capturan el sentido de sublevación, mientras que el inglés enfatiza la naturaleza adversarial de la acción. Se trata de un movimiento organizado y colectivo de confrontación, no de un conflicto individual, lo cual refleja la gravedad de la oposición que enfrentaban los apóstoles en su misión evangelizadora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2722', 'spa', 'Retener firmemente; reprimir o suprimir; poseer u ocupar; en voz pasiva, estar retenido o atado; en sentido náutico, dirigirse hacia un destino. Const', 'Retener firmemente; reprimir o suprimir; poseer u ocupar; en voz pasiva, estar retenido o atado; en sentido náutico, dirigirse hacia un destino. Construido a partir de κατά + ἔχω (''sujetar hacia abajo''), este verbo porta la imagen central de mantener un agarre firme, ya sea sobre una tradición apreciada o sobre una persona que no se quiere soltar. Pablo exhorta a los tesalonicenses a ''retener lo bueno'' (1 Ts 5:21), mientras que en Romanos 1:18 los impíos ''reprimen la verdad con injusticia''. La misma palabra describe poseer bienes (2 Co 6:10), estar cautivo por enfermedad (Jn 5:4) y dirigir un barco hacia la costa (Hch 27:40).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2723', 'spa', 'Acusar o presentar cargos contra alguien, generalmente en un contexto judicial; en voz pasiva, ser acusado o enfrentar cargos.', 'Acusar o presentar cargos contra alguien, generalmente en un contexto judicial; en voz pasiva, ser acusado o enfrentar cargos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2724', 'spa', 'Acusación, cargo, imputación; la presentación formal de cargos contra alguien', 'Este sustantivo designa una acusación o cargo, la declaración formal de una falta cometida contra alguien. En Juan 18:29, Pilato pregunta: «¿Qué acusación traéis contra este hombre?». En 1 Timoteo 5:19 se instruye: «No admitas acusación contra un anciano sino con el testimonio de dos o tres testigos». Tito 1:6 requiere que los hijos de un obispo sean creyentes, «que no estén acusados de disolución ni de rebeldía». El uso clásico abarca la acusación, la protesta formal y, en lógica, la predicación y las categorías. En el Nuevo Testamento su uso es forense y eclesial: cargos legales (Juan) y procedimientos de disciplina eclesiástica (Epístolas Pastorales).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2725', 'spa', 'Acusador; quien presenta cargos formales contra otro, especialmente en un proceso legal o judicial.', 'Κατήγορος es el término jurídico griego estándar para un fiscal o acusador: la persona que se presenta en un tribunal para hablar en contra del acusado. En el NT aparece exclusivamente en contextos judiciales. Jesús pregunta a la mujer sorprendida en adulterio «¿Dónde están tus acusadores?» (Jn 8:10). En Hechos, el procedimiento legal romano exige la presencia de los acusadores: los de Pablo son convocados (Hch 23:30, 35), Tértulo actúa como acusador ante Félix (Hch 24:8), y Festo insiste en que el acusado debe enfrentar a sus acusadores (Hch 25:16). Apocalipsis 12:10 llama a Satanás «el acusador de nuestros hermanos».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2726', 'spa', 'Abatimiento, pesadumbre o semblante decaído causado por la tristeza o la vergüenza', 'Este sustantivo describe el estado visible de estar emocionalmente abatido, donde el dolor o la vergüenza hacen que el semblante decaiga. Santiago 4:9 exhorta a los que lloran a cambiar su risa por esta condición sombría como parte de un arrepentimiento humilde. El léxico griego indica que se trata de una tristeza que hace mirar hacia abajo, en contraste con la alegría. Tanto el término griego κατήφεια como el español «abatimiento» subrayan esa pesadez interior que se refleja en el rostro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2727', 'spa', 'Instruir oralmente, catequizar; informar o comunicar — la raíz del castellano ''catecismo''', 'El verbo κατηχέω significaba originalmente ''resonar desde arriba'', pero en el siglo I se había asentado en dos usos distintos: la instrucción oral sistemática y la transmisión de información. En Lucas 1:4, Lucas escribe para que Teófilo conozca la certeza de las cosas en las que fue ''catequizado'', y en Gálatas 6:6 el que es ''instruido'' comparte con quien le enseña. De esta palabra derivan los términos castellanos ''catecismo'', ''catequesis'' y ''catequizar'', que conservan el sentido de instrucción religiosa metódica. Un uso más restringido en Hechos 21 significa simplemente ser informado o enterado de algo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2728', 'spa', 'Oxidarse, corroerse o deteriorarse por efecto de la herrumbre o la descomposición', 'Este verbo, en su forma pasiva, describe el proceso por el cual un metal se deteriora a causa de la herrumbre o la corrosión. Santiago 5:3 lo emplea metafóricamente para ilustrar cómo la riqueza acumulada se corroe y se convierte en testimonio contra quienes atesoran bienes en lugar de usarlos con justicia. La imagen evoca tanto la degradación física del metal como la degradación moral de la avaricia. El óxido que consume el oro y la plata sirve de acusador silencioso ante el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2729', 'spa', 'Prevalecer contra, vencer, ser lo suficientemente fuerte; tener fuerza o poder superior', 'Este verbo significa prevalecer contra, vencer o demostrar ser más fuerte que la oposición. En Mateo 16:18, Jesús pronuncia su célebre promesa: «Las puertas del Hades no prevalecerán contra» la iglesia. Lucas 21:36 exhorta a velar y orar «para que tengáis fuerza para escapar de todo esto» y estar en pie ante el Hijo del Hombre. En Lucas 23:23 se describe la insistencia de la multitud: «sus voces prevalecieron» al exigir la crucifixión de Jesús. Los usos neotestamentarios abarcan la promesa divina sobre la indestructibilidad de la iglesia, la preparación espiritual para resistir, y la persistencia de una multitud cuyas voces se imponen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2730', 'spa', 'Habitar, morar, establecerse; residir en un lugar como habitante permanente', 'Habitar, morar, establecerse; residir en un lugar como habitante permanente');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2731', 'spa', 'Morada, lugar de habitación o sitio de residencia', 'Este término designa un lugar donde alguien se establece y vive, ya sea de manera temporal o permanente. Marcos 5:3 lo emplea para describir los sepulcros donde el endemoniado gadareno hacía su morada, una habitación antinatural que subraya su alienación de la sociedad normal. Las distintas traducciones en múltiples lenguas convergen en el concepto de espacio residencial, aunque en este contexto la morada resulta especialmente trágica por tratarse de un lugar destinado a los muertos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2733', 'spa', 'Habitación, lugar de asentamiento o región destinada para morar', 'Este sustantivo se refiere a lugares de habitación o asentamiento, con un uso clásico que se extiende a colonias, granjas y zonas residenciales designadas. Hechos 17:26 lo emplea en el sermón de Pablo en Atenas, donde Dios determina los tiempos y las fronteras de las habitaciones humanas sobre la tierra. El término conlleva matices de providencia divina en el establecimiento de dónde moran los pueblos, señalando que la geografía humana no es producto del azar sino del designio soberano de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2734', 'spa', 'Contemplar o mirar como en un espejo; reflejar o examinar el propio reflejo', 'Este verbo evoca la imagen de observar algo tal como se refleja en un espejo, ya sea contemplando la propia imagen o meditando sobre algo a través de su reflejo. En 2 Corintios 3:18, Pablo lo utiliza para describir a los creyentes que contemplan la gloria del Señor, aunque los eruditos debaten si el sentido es reflejar esa gloria o contemplarla como en un espejo claro. La idea central es una meditación visual sostenida que produce transformación progresiva en quien contempla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2735', 'spa', 'logro recto, acción virtuosa, éxito moral; lo que se realiza correcta y virtuosamente', 'Sustantivo neutro que designa el éxito, el logro recto o la acción virtuosa: algo realizado correctamente. Los filósofos clásicos lo distinguen de la mera buena fortuna (εὐτύχημα): un κατόρθωμα resulta de la virtud y la destreza, no de la suerte. En la ética estoica, estas son «acciones perfectas» que cumplen todos los deberes, opuestas a los pecados (ἁμαρτήματα). Los críticos literarios lo usan para la excelencia estilística. La palabra implica no solo éxito sino rectitud: calidad moral en el logro. El Nuevo Testamento lo emplea (en variantes textuales) para obras justas realizadas mediante la fe. Significado raíz: lo que se endereza, se hace recto, se perfecciona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2736', 'spa', 'Abajo, debajo, bajo — adverbio espacial que indica dirección descendente o posición inferior a lo largo de un eje vertical. El adverbio κάτω (kato) ex', 'Abajo, debajo, bajo — adverbio espacial que indica dirección descendente o posición inferior a lo largo de un eje vertical. El adverbio κάτω (kato) expresa dirección descendente o posición inferior. Satanás tienta a Jesús a arrojarse ''abajo'' desde el pináculo del templo (Mt 4:6; Lc 4:9). En la crucifixión, el velo del templo se rasga de arriba ''abajo'' (Mt 27:51; Mr 15:38). Pedro se calienta ''abajo'' en el patio mientras Jesús es juzgado arriba (Mr 14:66). Jesús le dice a Nicodemo que lo nacido de la carne es ''de abajo'' mientras que lo nacido del Espíritu es de arriba (Jn 8:23). El uso de umbral comparativo aparece en la matanza de Herodes de los niños ''de dos años para abajo'' (Mt 2:16). Español abajo, árabe أَسفَل, hindi नीचे, coreano 아래로 y suajili chini, todos expresan el concepto espacial descendente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2737', 'spa', 'Inferior, más abajo o en posición más baja; forma comparativa de ''abajo''', 'Este adjetivo comparativo describe algo situado en una posición más baja o inferior en términos espaciales. Efesios 4:9 lo emplea al hablar del descenso de Cristo, refiriéndose a «las partes más bajas de la tierra», aludiendo posiblemente a su encarnación en la tierra (más baja que el cielo) o a su descenso al sepulcro. La evidencia multilingüe respalda uniformemente la comparación espacial: inferior, más bajo. Esta imagen espacial sustenta el argumento de Pablo sobre el movimiento cósmico de Cristo entre descenso y ascensión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2739', 'spa', 'Abrasar o quemar con calor intenso; en voz pasiva, ser abrasado o consumido por el fuego.', 'Describe el efecto destructivo de un calor abrasador e intenso. En la parábola del sembrador, la semilla que cae en terreno pedregoso brota rápidamente pero es quemada por el sol porque carece de raíz (Mt 13:6; Mc 4:6), una imagen vívida de la fe superficial que se marchita bajo la presión. En Apocalipsis 16:8-9, la cuarta copa de la ira otorga al sol el poder de abrasar a los hombres con fuego, y sin embargo estos se niegan a arrepentirse. El verbo transmite siempre un calor feroz y destructivo, nunca una tibieza agradable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2740', 'spa', 'Quema, combustión o el acto de ser consumido por el fuego', 'Este sustantivo se refiere al proceso o resultado de la quema. En el uso clásico abarca la quema sacrificial, la cauterización médica y la fundición de metales. Hebreos 6:8 lo emplea como advertencia: la tierra improductiva que da espinos y abrojos está destinada a ser quemada, imagen del juicio divino tomada de la práctica agrícola. La quema representa tanto el proceso de destrucción como su propósito purificador dentro de este contexto escatológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2742', 'spa', 'Calor abrasador, viento sofocante; calor intenso y opresivo típico del siroco del Medio Oriente', 'Esta palabra describe el calor intenso y opresivo propio de los climas mediterráneo y del Cercano Oriente. El siroco, un viento cálido y polvoriento que sopla desde el desierto, trae un calor abrasador capaz de marchitar la vegetación y hacer insoportable el trabajo al aire libre. Jesús emplea esta imagen en Mateo 20:12, donde los obreros de la viña se quejan de haber soportado la carga y el calor sofocante del día. Santiago 1:11 la utiliza como metáfora de la rapidez con que se desvanece el rico, tal como el viento ardiente marchita la hierba y hace caer sus flores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2743', 'spa', 'Ser cauterizado, marcado a fuego; tener la conciencia endurecida como si estuviera quemada', 'Este verbo en voz pasiva significa literalmente ser marcado o cauterizado con hierro candente, término proveniente tanto de la esclavitud como de la medicina. 1 Timoteo 4:2 lo usa metafóricamente para describir conciencias cauterizadas, es decir, insensibilizadas por la transgresión repetida, como el tejido cicatricial que ya no siente. La imagen médica transmite la idea de una sensibilidad moral anulada, donde la persona ya no percibe la convicción del bien y del mal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2744', 'spa', 'Jactarse, gloriarse o exultar en algo; una variante textual produce ''ser quemado'' (1 Co 13:3)', 'Jactarse, gloriarse o exultar en algo; una variante textual produce ''ser quemado'' (1 Co 13:3)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2745', 'spa', 'Motivo de jactancia, base para gloriarse — el objeto, fundamento o asunto en el cual uno se enorgullece; aquello de lo que uno se gloría. El sustantiv', 'Motivo de jactancia, base para gloriarse — el objeto, fundamento o asunto en el cual uno se enorgullece; aquello de lo que uno se gloría. El sustantivo καύχημα (kauchēma) denota el objeto o fundamento de la jactancia — la cosa concreta que uno señala con orgullo, distinto de καύχησις que es el acto de jactarse. Abraham podría tener un motivo de jactancia ante los hombres, pero no ante Dios (Ro 4:2). El propio ''motivo de gloria'' de Pablo es predicar el evangelio gratuitamente (1 Co 9:15-16), mientras que la jactancia de los corintios carece de fundamento cuando toleran el pecado (1 Co 5:6). Los creyentes serán el motivo de gloria de Pablo en el retorno de Cristo (2 Co 1:14; Fil 1:26; 2:16). Gálatas 6:4 exhorta a examinar la propia obra para que el motivo de gloria se sostenga por sus propios méritos. Español ''motivo de jactancia'' y alemán ''Ruhm'' captan el carácter objetivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2746', 'spa', 'Jactancia, acto de gloriarse — la accion o ejercicio de jactarse, exultar o enorgullecerse de algo. El sustantivo καύχησις (kauchēsis) designa el acto', 'Jactancia, acto de gloriarse — la accion o ejercicio de jactarse, exultar o enorgullecerse de algo. El sustantivo καύχησις (kauchēsis) designa el acto de jactarse, es decir, la actividad en si misma, a diferencia de καύχημα que es aquello de lo que uno se jacta. Pablo pregunta ''¿donde queda entonces la jactancia?'' y responde que queda excluida por la ley de la fe (Rom 3:27). Su jactancia respecto a los corintios resulta bien fundada (2 Cor 7:4, 14; 8:24), y su conciencia confirma que su jactancia en una conducta santa es sincera (2 Cor 1:12). Insiste en que nadie le impedira gloriarse de predicar sin cobrar (2 Cor 11:10). Los tesalonicenses son su ''corona de jactancia'' (1 Tes 2:19). Santiago advierte que jactarse de planes mundanos es malo (Stg 4:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2748', 'spa', 'Cedro o el valle de Cedrón (nombrado por los cedros o por la oscuridad)', 'Aunque la entrada léxica describe extensamente los cedros y sus productos madereros, la única aparición en el Nuevo Testamento usa este término como topónimo: el valle de Cedrón, situado entre Jerusalén y el Monte de los Olivos. Juan 18:1 señala este lugar como el que Jesús cruzó antes de su arresto en Getsemaní. Las transliteraciones en diversas lenguas (Kedron, Kédrōn, Cédron, Kidron) conservan el nombre hebreo, cuya etimología puede relacionarse tanto con los cedros como con la oscuridad o turbidez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2749', 'spa', 'Yacer, estar puesto, reclinarse; de objetos colocados, personas acostadas, cosas establecidas, ciudades situadas o personas designadas/destinadas.', 'Yacer, estar puesto, reclinarse; de objetos colocados, personas acostadas, cosas establecidas, ciudades situadas o personas designadas/destinadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2750', 'spa', 'Vendas funerarias, bandas de tela o tiras de lienzo usadas para envolver un cadáver', 'Este sustantivo originalmente se refería a las cintas de los bastidores de cama, pero pasó a designar las vendas o bandas usadas en la preparación funeraria. Juan 11:44 retrata a Lázaro saliendo del sepulcro aún atado con estas vendas mortuorias, subrayando la realidad física del milagro. La imagen de las vendas funerarias es vívida: Lázaro necesita que otros lo desaten, lo cual simboliza la liberación de la muerte con la participación de la comunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2751', 'spa', 'Trasquilar o cortar el cabello; usado para esquilar ovejas y rapar el cabello humano, especialmente en relación con votos.', 'Verbo antiguo que designa el acto de cortar el pelo o la lana, con significado tanto agrícola como ritual en el Nuevo Testamento. En Hechos 8:32, Felipe lee de Isaías 53 donde el Siervo Sufriente es comparado con una oveja muda ante el que la esquila, imagen poderosa de inocencia sumisa. En Hechos 18:18, Pablo se rapa la cabeza en Cencrea a causa de un voto, probablemente de tipo nazareo. Luego Pablo emplea el término en 1 Corintios 11:6 al tratar sobre el velo, argumentando que si una mujer rehúsa cubrirse la cabeza, bien podría raparse, insinuando que ir rapada conllevaba vergüenza social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2752', 'spa', 'Voz de mando, grito de autoridad o llamamiento soberano que exige respuesta inmediata', 'Este sustantivo designa un mandato enérgico o convocatoria autoritativa, empleado originalmente para órdenes militares, la señal del cómitre a los remeros o el grito del auriga a los caballos. En 1 Tesalonicenses 4:16, Pablo lo utiliza para describir el grito de mando que acompañará el regreso de Cristo, junto con la voz del arcángel y la trompeta de Dios. No se trata de un habla ordinaria, sino de una orden soberana que exige obediencia inmediata y pone en movimiento la resurrección de los muertos. La expresión castellana ''voz de mando'' capta bien este matiz militar y autoritativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2753', 'spa', 'Mandar, ordenar: dirigir a alguien con autoridad, emitiendo una instrucción vinculante.', 'Mandar, ordenar: dirigir a alguien con autoridad, emitiendo una instrucción vinculante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2754', 'spa', 'Vanagloria, presunción vacía o ambición por un honor carente de valor real', 'Este sustantivo describe el vicio de buscar una gloria hueca, un honor que carece de sustancia o que nace de motivos indebidos. En Filipenses 2:3, Pablo lo contrasta con la humildad que pone al otro por delante, advirtiendo a los creyentes contra toda acción motivada por la ambición vacía o el orgullo competitivo. Tanto el español ''vanagloria'' como el compuesto alemán ''leere Ehre'' (honor vacío) subrayan cómo esta gloria es hueca, desprovista de verdadero valor o de aprobación divina. Es la antítesis del vaciamiento de sí mismo que Cristo ejemplificó.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2755', 'spa', 'Vanaglorioso, engreído o caracterizado por un orgullo vacío y autoglorificación', 'Este adjetivo describe a personas dominadas por la vanidad o el orgullo hueco. En Gálatas 5:26, Pablo advierte contra volverse vanagloriosos, vinculando este vicio con la provocación y la envidia mutua, frutos relacionales del orgullo. El español ''vanagloriosos'' y el alemán ''ruhmsüchtig'' (ávido de fama) subrayan la búsqueda activa de un honor vacío. Este defecto socava la vida comunitaria guiada por el Espíritu, fomentando la competencia en lugar del servicio mutuo y el reconocimiento gozoso de los dones ajenos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2756', 'spa', 'Vacío, vano, sin resultado ni sustancia; también con las manos vacías o insensato cuando se aplica a personas. Κενός describe la condición de estar de', 'Vacío, vano, sin resultado ni sustancia; también con las manos vacías o insensato cuando se aplica a personas. Κενός describe la condición de estar desprovisto, ya sea de contenido, propósito o entendimiento. Pablo lo usa con fuerza para advertir que la fe sin la resurrección sería ''vana'' (1 Co 15:14), y que los creyentes no deben recibir la gracia de Dios ''en vano'' (2 Co 6:1). En las parábolas, los labradores despiden a los siervos ''con las manos vacías'' (Mc 12:3; Lc 20:10-11), y el Magnificat de María celebra que Dios despidió a los ricos ''vacíos'' (Lc 1:53). Santiago lo emplea como vocativo punzante -- ''¡Oh hombre insensato!'' (Stg 2:20) -- donde la vacuidad se convierte en metáfora de necedad espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2758', 'spa', 'Vaciar, anular o dejar sin efecto; usado del anonadamiento de Cristo y de cosas despojadas de su fuerza.', 'Contiene la idea raíz de dejar algo vacío o hueco, drenándolo de su contenido, significado o poder. El uso más célebre es Filipenses 2:7, donde Cristo «se vació a sí mismo» — el gran pasaje de la kénosis que fundamenta la teología cristiana de la encarnación. En otros textos, Pablo lo aplica a argumentos teológicos: la fe quedaría vaciada de sentido si la justicia viniera por la ley (Ro 4:14), y la cruz perdería su poder ante la retórica ingeniosa (1 Co 1:17). La imagen concreta de vaciar un recipiente se extiende metafóricamente a lo largo del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2759', 'spa', 'Punta aguda: aguijón para arrear animales, o aguijón (de insecto o de la muerte personificada).', 'Designa cualquier punta aguda y penetrante: un aguijón para bueyes, el aguijón de una criatura, o figuradamente el dardo doloroso de la muerte. En Hechos 9:5 y 26:14, Cristo resucitado dice a Pablo que es difícil «dar coces contra el aguijón», tomando un conocido proverbio griego sobre la resistencia inútil a la dirección divina. Pablo transforma luego la imagen en clave escatológica en 1 Corintios 15:55-56, preguntando triunfalmente: «¿Dónde está, oh muerte, tu aguijón?», siendo el aguijón el pecado. Apocalipsis 9:10 retorna al sentido literal con criaturas semejantes a escorpiones cuyos aguijones están en sus colas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2760', 'spa', 'Centurión; oficial militar romano al mando de aproximadamente cien soldados', 'Préstamo del latín (de centurio) que designa a un oficial romano al mando de una centuria, aproximadamente cien hombres, aunque el número real variaba. Los centuriones eran la columna vertebral de la estructura militar romana, responsables del entrenamiento, la disciplina y el liderazgo de sus unidades en batalla. El Evangelio de Marcos emplea este término exclusivamente en la narración de la pasión, donde el centurión al pie de la cruz se convierte en el primer gentil en confesar a Jesús como Hijo de Dios (Marcos 15:39). La palabra refleja la presencia militar romana que impregnaba la Judea del siglo primero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2761', 'spa', 'En vano, de manera vacía, sin propósito ni resultado; infructuosamente', 'Este adverbio, derivado del adjetivo que significa ''vacío'', expresa la idea de hacer algo en vano o sin efecto alguno. Santiago 4:5 lo emplea en una afirmación algo enigmática sobre la Escritura, que no habla ''en vano'' ni ''sin propósito''. El español ''en vano'' y el alemán ''vergeblich'' captan bien la idea de esterilidad e inutilidad. El término subraya que la palabra divina verdadera siempre cumple su propósito; cada declaración de Dios lleva peso y produce el efecto para el cual fue pronunciada, a diferencia de las palabras humanas que pueden resultar vacías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2763', 'spa', 'Alfarero; artesano que moldea vasijas de barro en un torno', 'El artesano que da forma a vasijas de barro usando un torno de alfarero. En el mundo antiguo, los alfareros eran artesanos esenciales que proporcionaban recipientes cotidianos para agua, aceite, grano y otras necesidades. La libertad del alfarero para moldear el barro a su voluntad se convirtió en una poderosa imagen bíblica de la soberanía de Dios sobre la creación. Pablo recurre a esta imagen en Romanos 9:21, preguntando si el barro puede cuestionar el derecho del alfarero a hacer distintos vasos para distintos propósitos. Mateo 27:7, 10 mencionan el campo del alfarero, comprado con el dinero de sangre de Judas en cumplimiento de la profecía de Jeremías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2764', 'spa', 'Hecho de barro o arcilla; de alfarería, cerámico', 'Este adjetivo describe objetos fabricados con arcilla de alfarero o pertenecientes al oficio de la alfarería. Apocalipsis 2:27 lo emplea en la expresión ''vasos de barro'', imagen tomada del Salmo 2 sobre la autoridad del Mesías para quebrantar las naciones rebeldes con la misma facilidad con que se rompen las vasijas de cerámica. El español ''de barro'' y el alemán ''töpfern'' (del alfarero) resaltan la fragilidad del material. Esta imagen pone de relieve la vulnerabilidad del poder terrenal ante la autoridad divina e irresistible de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2766', 'spa', 'Tejas, tejas de barro para techumbre o cubierta cerámica de tejado', 'Este sustantivo designa las tejas de cerámica o barro utilizadas como cubierta de tejado, aunque también podría aludir a vasijas de alfarería o al conjunto del entejado. En Lucas 5:19 se describe cómo los amigos del paralítico quitaron las tejas del techo para descolgarlo hasta donde estaba Jesús. Este detalle vívido subraya tanto la determinación de la fe como las prácticas constructivas típicas de las casas palestinas, cuyos techos planos eran accesibles y permitían este tipo de intervención audaz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2767', 'spa', 'Mezclar, combinar; unir líquidos, especialmente vino con agua u otras sustancias', 'En el mundo mediterráneo antiguo, el vino se mezclaba habitualmente con agua antes de beberlo; consumirlo puro se consideraba propio de bárbaros. Este verbo describe ese proceso de mezcla, aunque podía aplicarse a cualquier combinación de líquidos. El Apocalipsis emplea esta palabra con notable fuerza teológica: la ira de Dios se «mezcla» sin diluir en la copa de su furor (14:10), y a Babilonia se le ordena recibir una doble porción de la mezcla que ella preparó para otros (18:6, dos veces). El lenguaje de mezclar evoca tanto la hospitalidad cotidiana como el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2768', 'spa', 'Cuerno — cuerno de un animal; simbolicamente, poder, autoridad o poderio real en visiones profeticas y apocalipticas. El sustantivo κέρας (keras) desi', 'Cuerno — cuerno de un animal; simbolicamente, poder, autoridad o poderio real en visiones profeticas y apocalipticas. El sustantivo κέρας (keras) designa el cuerno de un animal, empleado tanto en sentido literal como en calidad de uno de los simbolos mas potentes de la Escritura. En el Benedictus, Zacarias alaba a Dios por levantar ''un cuerno de salvacion'' en la casa de David (Lc 1:69), recurriendo a la imagen veterotestamentaria del cuerno como poder concentrado. Apocalipsis explota ampliamente el simbolo: el Cordero tiene siete cuernos que significan poder completo (Ap 5:6), el dragon tiene diez cuernos (Ap 12:3), y la bestia del mar lleva diez cuernos con diademas que representan reyes vasallos (Ap 13:1, 11; 17:3-16). Los cuernos del altar de oro aparecen en Apocalipsis 9:13, evocando el diseno del altar de Exodo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2769', 'spa', 'Algarrobas, vainas del algarrobo usadas como alimento para animales y los más pobres', 'Este sustantivo diminutivo designa principalmente las algarrobas, el fruto comestible del algarrobo que servía como forraje para animales y alimento de hambruna. En Lucas 15:16 se describe al hijo pródigo en tal estado de miseria que anhelaba llenarse el estómago con las algarrobas destinadas a los cerdos. Este detalle pone de relieve la profundidad de su degradación: un hijo judío reducido a envidiar la comida de animales impuros que él mismo apacentaba, sin poder siquiera obtener este sustento ínfimo, lo cual finalmente lo impulsa al arrepentimiento y al regreso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2770', 'spa', 'Ganar, obtener, lograr beneficio; ganar personas, obtener rendimiento económico, conseguir algo valioso o evitar una pérdida. Del sustantivo κέρδος (g', 'Ganar, obtener, lograr beneficio; ganar personas, obtener rendimiento económico, conseguir algo valioso o evitar una pérdida. Del sustantivo κέρδος (ganancia, ventaja), este verbo abarca con notable flexibilidad tanto la ganancia material como la espiritual. En las parábolas de los talentos (Mt 25:16-22) se trata de beneficio comercial directo. Pero Pablo redefine radicalmente la palabra: considera todas las cosas como pérdida ''a fin de ganar a Cristo'' (Fil 3:8), y se hace ''todo para todos, para ganar a algunos'' (1 Co 9:19-22). El mismo verbo que cuenta monedas en un libro de cuentas ahora cuenta almas para el reino. Un uso náutico singular en Hechos 27:21 -- ''ganar'' en el sentido de evitar daño -- completa su alcance semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2771', 'spa', 'Ganancia, provecho; ventaja o beneficio obtenido, ya sea material o espiritual', 'Esta palabra abarca tanto la ganancia material como la ventaja o el beneficio en un sentido más amplio. Aunque puede referirse al lucro económico, el Nuevo Testamento la emplea de maneras más profundas. Pablo la usa paradójicamente en Filipenses 1:21 — «para mí el vivir es Cristo y el morir es ganancia» — donde la muerte misma se convierte en provecho porque significa estar con Cristo. En Filipenses 3:7, considera como pérdida lo que antes contaba como ventaja, por causa de Cristo. Tito 1:11 advierte contra los falsos maestros motivados por ganancias deshonestas. La palabra invita a reflexionar sobre lo que verdaderamente valoramos como provechoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2772', 'spa', 'Monedas pequeñas, calderilla o dinero en forma de moneda (especialmente de cobre)', 'Este término se refiere a monedas o calderilla, a menudo específicamente monedas de cobre en contraposición a las de plata. En Juan 2:15 se describe cómo Jesús volcó las mesas y desparramó las monedas de los cambistas en el templo. Las traducciones multilingües convergen en el concepto de moneda acuñada. Este detalle resalta tanto la profanación comercial del espacio sagrado como la contundencia total de la acción profética de Jesús, con las monedas rodando por los atrios del templo mientras los mercaderes se afanaban por recogerlas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2773', 'spa', 'Cambista, persona dedicada al cambio de moneda en el templo o el mercado', 'Este sustantivo designa a quienes cambiaban diversas monedas extranjeras por el siclo del templo, necesario para las ofrendas. En Juan 2:14 se menciona a los cambistas entre aquellos a quienes Jesús expulsó de los atrios del templo. Aunque su servicio era necesario, ya que las monedas romanas o griegas no eran aceptables para el impuesto del templo, la acción de Jesús sugiere que su práctica se había vuelto abusiva o que su ubicación dentro del recinto sagrado era inapropiada, convirtiendo la casa de oración en un centro de lucro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2775', 'spa', 'Golpear en la cabeza; herir o maltratar a alguien en la cabeza', 'Este verbo significa golpear a alguien en la cabeza, aunque en el griego clásico también podía significar ''resumir'' o ''recapitular'' (traer bajo un mismo encabezado). En Marcos 12:4 aparece en la parábola de los labradores malvados, donde un siervo es golpeado en la cabeza por quienes rechazan la autoridad del dueño de la viña. La traducción al español ''hirieron en la cabeza'' explicita el objetivo anatómico del golpe. Este detalle violento subraya la escalada de rebeldía contra la autoridad legítima, violencia que culminará en el asesinato del hijo amado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2776', 'spa', 'Cabeza — la parte anatómica del cuerpo; figuradamente, autoridad, preeminencia u origen.', 'κεφαλή porta tanto un significado anatómico concreto como una rica extensión figurada que se tornó teológicamente decisiva. Literalmente se refiere a la cabeza física de una persona o animal: la cabeza sobre la que no se puede hacer un solo cabello blanco o negro (Mt 5:36), la cabeza ungida con aceite (Mt 6:17), la cabeza de Juan el Bautista en una bandeja (Mt 14:8). Figuradamente, Pablo desarrolla κεφαλή como término clave para la autoridad y el orden relacional: Cristo como ''cabeza'' de la iglesia (Ef 1:22; 5:23) y el marido como ''cabeza'' de la mujer (1 Co 11:3). El español ''cabeza'' preserva este doble alcance literal y figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2777', 'spa', 'Rollo de escritura, pergamino enrollado o documento en forma de volumen', 'Este diminutivo de ''cabeza'' pasó a designar la perilla del rodillo de un pergamino y, por extensión, el rollo mismo. Hebreos 10:7 cita el Salmo 40: ''en el rollo del libro está escrito de mí,'' donde Cristo habla de la profecía mesiánica consignada en las Escrituras. La imagen evoca un documento que debe desenrollarse y leerse, conectando la venida de Cristo con el testimonio profético escrito. El rollo representa así la totalidad del registro escritural que apunta hacia el Mesías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2778', 'spa', 'Tributo personal; impuesto por cabeza basado en un censo, préstamo del latín census al griego koiné.', 'Préstamo del latín census, este término designa un impuesto per cápita impuesto por Roma a los pueblos sometidos. En los Evangelios se convierte en el detonante de una célebre pregunta trampa: «¿Es lícito pagar el κῆνσος al César?» (Mt 22:17; Mc 12:14). La palabra lleva una carga política considerable: pagarlo implicaba reconocer la soberanía romana, razón por la cual la pregunta resultaba tan incendiaria. Se trata de una exacción obligatoria, personal y directa, distinta de los impuestos sobre bienes o propiedades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2779', 'spa', 'Huerto, jardín; espacio cultivado y cercado, a menudo un vergel o plantación, con resonancias tanto agrícolas como sagradas.', 'Designa un terreno cultivado y cerrado — un huerto o jardín. En los Evangelios aparece casi exclusivamente en contextos joánicos: el huerto al otro lado del Cedrón donde Jesús fue arrestado (Jn 18:1, 26) y el huerto con la tumba nueva donde fue sepultado y resucitó (Jn 19:41). Lucas 13:19 lo emplea en la parábola del grano de mostaza, donde un hombre siembra la semilla en ''su huerto''. La palabra porta una rica carga simbólica en la tradición griega y judía — desde los jardines de Adonis hasta el Jardín del Edén — confiriendo a sus apariciones neotestamentarias en el arresto y la resurrección una hondura silenciosa pero profunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2780', 'spa', 'Jardinero, persona que cuida y cultiva un jardín o huerto', 'Este sustantivo designa a quien trabaja y mantiene un jardín. En Juan 20:15, María Magdalena supone inicialmente que Jesús resucitado es el jardinero del huerto donde estaba la tumba. Esta identidad equivocada está cargada de profunda ironía: ella confunde al autor de la vida con alguien que cuida plantas, y al nuevo Adán con un simple cuidador de huertos. El malentendido resalta el contraste entre la apariencia humilde y la realidad gloriosa de la resurrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2781', 'spa', 'panal de miel; las celdillas de cera llenas de miel, usado también metafóricamente para la dulzura', 'Significa principalmente panal de miel: la estructura de cera que las abejas construyen para almacenar miel. Homero y los autores clásicos lo mencionan junto a la miel como sustancia preciada. La Septuaginta lo emplea en la descripción de Proverbios sobre las palabras agradables («panal de miel»). La medicina antigua utilizaba el panal en tratamientos. Metafóricamente representa dulzura y placer: los poetas llamaban κηρίον a los libros de poemas, y los moralistas hablaban del panal del deseo. En medicina se usa también para una afección cutánea que semeja la estructura del panal. Forma diminutiva de κηρός (cera), abarca tanto las celdillas como su dulce contenido, inseparables en la experiencia antigua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2782', 'spa', 'Proclamación, predicación — el contenido o acto de pregonar un mensaje públicamente, especialmente el anuncio apostólico del evangelio', 'Κήρυγμα es uno de los grandes términos técnicos del cristianismo primitivo, que designa la proclamación pública del mensaje evangélico. Derivado de κηρύσσω (''pregonar''), puede referirse tanto al acto de predicar como al contenido de lo predicado, y a menudo a ambos simultáneamente. La célebre declaración de Pablo de que ''agradó a Dios salvar a los creyentes por la locura de la predicación'' (1 Co 1:21) juega con este doble sentido: el mensaje suena insensato y el método de proclamación abierta parece débil, pero Dios eligió precisamente esa combinación. Jesús invoca ''la predicación de Jonás'' (Mt 12:41; Lc 11:32) como modelo de proclamación que produjo arrepentimiento. La palabra conlleva el peso de un anuncio oficial y autoritativo, no una conversación privada sino un pregón público.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2783', 'spa', 'Heraldo, pregonero; quien hace proclamaciones públicas o anuncia mensajes importantes', 'En el mundo antiguo, los heraldos servían como mensajeros oficiales que proclamaban decretos, anunciaban noticias y mantenían el orden en las asambleas públicas. Eran personas protegidas cuya función era comunicar, no crear los mensajes. El Nuevo Testamento se apropia de esta imagen para la proclamación del evangelio: el heraldo no inventa el mensaje, sino que anuncia fielmente el decreto del Rey. Pablo se identifica como heraldo del evangelio en 1 Timoteo 2:7 y 2 Timoteo 1:11. Pedro llama a Noé «pregonero de justicia» (2 Pedro 2:5), destacando su papel como portavoz de Dios que advertía del juicio venidero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2784', 'spa', 'Proclamar públicamente, predicar, pregonar; anunciar un mensaje con autoridad.', 'El verbo κηρύσσω evoca la imagen de un heraldo (κῆρυξ) que realiza una proclamación pública y autoritativa. En el griego clásico describía al pregonero de la ciudad o al oficial que anunciaba juegos y tratados; en el Nuevo Testamento se convierte en el verbo principal para predicar el evangelio. Juan el Bautista ''proclamó'' el arrepentimiento en el desierto (Mt 3:1), Jesús ''predicó'' el reino por toda Galilea (Mt 4:23), y el Señor resucitado comisionó a sus seguidores a ''proclamar'' las buenas nuevas a toda criatura (Mr 16:15). La palabra insiste en un anuncio público, vocal y autoritativo, no en persuasión privada ni discurso filosófico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2785', 'spa', 'Gran criatura marina, monstruo del mar o pez enorme (incluidas las ballenas)', 'Este término abarca grandes criaturas marinas, incluyendo ballenas, monstruos del mar y peces enormes. Mateo 12:40 lo emplea para referirse al ''gran pez'' que tragó a Jonás, episodio que Jesús utiliza como señal profética de su muerte y resurrección venideras. La ambigüedad sobre la especie exacta importa menos que la tipología de la señal: tres días en el vientre de la muerte antes de la liberación. Así como Jonás fue devuelto a la vida, el Hijo del Hombre emergerá del sepulcro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2786', 'spa', 'Cefas — nombre arameo que significa ''roca'', dado por Jesús a Simón Pedro, usado especialmente por Pablo', 'Κηφᾶς es el equivalente arameo del griego Πέτρος (''roca''), el nombre que Jesús otorgó a Simón (Jn 1:42). Lo que distingue esta forma es su distribución: mientras los Evangelios usan abrumadoramente ''Pedro'', Pablo emplea casi exclusivamente ''Cefas'' en sus cartas (1 Co 1:12; 3:22; 9:5; 15:5; Gá 1:18; 2:9,11,14). Esta preferencia refleja probablemente el contacto directo de Pablo con la iglesia de Jerusalén de habla aramea, donde el apóstol era conocido por su nombre semítico. El arameo kepha (''roca, piedra'') se conserva intacto mediante transliteración griega, recordando a los lectores que el apóstol fundacional de la iglesia llevaba un nombre arraigado en la lengua materna de Jesús. Solo Juan 1:42 explica el significado del nombre para los lectores griegos, traduciéndolo como Πέτρος.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2787', 'spa', 'κιβωτός — arca; recipiente grande en forma de cofre, usado para el arca de Noé y el Arca del Pacto.', 'Κιβωτός designa un cofre o recipiente grande con forma de caja. En el Nuevo Testamento posee dos referentes bíblicos distintos que comparten la imagen subyacente de un contenedor cerrado y protector: el arca de Noé, la gran embarcación de salvación (Matt 24:38; Heb 11:7; 1 Pet 3:20), y el Arca del Pacto, el cofre revestido de oro en el Lugar Santísimo que contenía las tablas de la Ley (Heb 9:4). El sentido clásico de ''cofre'' para guardar documentos cede por completo en las Escrituras a estos dos referentes de profundo peso teológico: uno es vaso de salvación frente al juicio, el otro el lugar de la presencia de Dios entre su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2788', 'spa', 'Cítara, lira; instrumento de cuerda usado en la adoración y la alabanza celestial.', 'Designa la κιθάρα, el emblemático instrumento de cuerdas del mundo mediterráneo antiguo — antepasado de nuestra palabra ''guitarra''. En el NT aparece tanto en la analogía paulina sobre producir notas musicales distinguibles (1 Co 14:7) como en las visiones apocalípticas de adoración celestial (Ap 5:8; 14:2; 15:2). El español ''cítara'' conserva la raíz griega original con total transparencia, mientras que el alemán Harfe y el francés cithare reflejan dos tradiciones de recepción distintas del mismo instrumento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2791', 'spa', 'Cilicia — provincia romana en la costa sureste de Asia Menor, tierra natal del apóstol Pablo', 'Κιλικία designa la provincia romana situada en la costa sureste de Asia Menor (la actual Turquía meridional), cuya capital era Tarso, lugar de nacimiento del apóstol Pablo (Hch 21:39; 22:3). La región aparece en Hechos en relación con los oponentes de la sinagoga helenística (Hch 6:9), la carta apostólica a los creyentes gentiles (Hch 15:23, 41) y el viaje marítimo de Pablo (Hch 27:5). El propio Pablo la menciona en Gálatas 1:21 como lugar que visitó tras su conversión. Las traducciones la transcriben uniformemente de forma fonética: en español ''Cilicia'', en francés ''Cilicie'', en alemán ''Kilikien''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2792', 'spa', 'Canela, especia aromática obtenida de la corteza del árbol de canelo', 'Este sustantivo se refiere a la valiosa especia aromática extraída de la corteza del árbol de canela, muy apreciada en el mundo antiguo. Apocalipsis 18:13 la incluye entre los artículos de lujo cuyo comercio cesa cuando cae Babilonia, subrayando el materialismo de aquel imperio comercial y la magnitud del juicio divino. La presencia de la canela en esta lista enfatiza tanto la extensión del comercio suntuario como su definitiva inutilidad ante el tribunal de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2793', 'spa', 'Estar en peligro, correr riesgo; arriesgar la propia seguridad o posición.', 'Describe la exposición a un riesgo grave o peligro inminente. El término abarca desde el peligro físico — como cuando la barca de los discípulos se anegaba (Lc 8:23) — hasta la amenaza institucional o social, como cuando Pablo advierte que el oficio de los plateros e incluso el templo de Artemisa ''corre peligro'' de ser desacreditado (Hch 19:27). Pablo también lo emplea para referirse a su propio peligro mortal cotidiano por causa del evangelio (1 Co 15:30). La expresión española ''correr peligro'' capta con precisión el sentido de exposición continua y presente a una amenaza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2794', 'spa', 'Peligro, riesgo; exposición a daño o muerte, especialmente en contextos de padecimientos sufridos por causa del evangelio.', 'Denota peligro o riesgo: el estado de estar expuesto a un daño grave o a la muerte. En el Nuevo Testamento, casi todas las apariciones de κίνδυνος se concentran en el famoso «catálogo de peligros» de Pablo en 2 Corintios 11:26, donde enumera peligros de ríos, de ladrones, de sus compatriotas, de los gentiles, en la ciudad, en el desierto, en el mar y de falsos hermanos. La repetición ocho veces en un solo versículo subraya la incesante amenaza que Pablo enfrentaba. Romanos 8:35 completa el panorama preguntando si el peligro puede separar a los creyentes del amor de Cristo.');